import type { BankQuestion } from "@/lib/bank";

/** Fundamental Rights (Indian Polity): 222 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"polity-fundamental-rights-1","question":"Fundamental Rights are contained in which Part of the Constitution?","options":["Part II","Part III","Part IV","Part IVA"],"answer":1,"explanation":"Part III (Articles 12–35) contains the Fundamental Rights. Part II is Citizenship, Part IV the Directive Principles and Part IVA the Fundamental Duties added in 1976.","difficulty":"easy"},
  {"id":"polity-fundamental-rights-2","question":"How many Fundamental Rights does the Constitution guarantee today?","options":["5","6","7","11"],"answer":1,"explanation":"Six: equality, freedom, against exploitation, religion, cultural and educational, and constitutional remedies. The trap is 7, the original count before the 44th Amendment (1978) removed the Right to Property; 11 is the number of Fundamental Duties and 5 the number of writs.","difficulty":"easy"},
  {"id":"polity-fundamental-rights-3","question":"Dr. B. R. Ambedkar described which Article as the “heart and soul” of the Constitution?","options":["Article 19","Article 21","Article 32","Article 368"],"answer":2,"explanation":"Article 32 (Right to Constitutional Remedies) lets citizens move the Supreme Court directly to enforce Fundamental Rights.","difficulty":"moderate"},
  {"id":"polity-fundamental-rights-4","question":"The Right to Education (Article 21A) was inserted by which Amendment?","options":["73rd Amendment","74th Amendment","86th Amendment","93rd Amendment"],"answer":2,"explanation":"The 86th Amendment Act, 2002 inserted Article 21A for free and compulsory education for children aged 6–14.","difficulty":"moderate"},
  {"id":"polity-fundamental-rights-5","question":"Fundamental Rights in the Indian Constitution were borrowed from the Constitution of:","options":["UK","USA","Ireland","Canada"],"answer":1,"explanation":"The justiciable Bill of Rights idea came from the US Constitution. Ireland gave India the Directive Principles, the UK parliamentary government and Canada the federation with a strong Centre, so those are the tempting mix-ups.","difficulty":"moderate"},
  {"id":"polity-fundamental-rights-6","question":"The Right to Property was removed from the list of Fundamental Rights by the:","options":["42nd Amendment","44th Amendment","52nd Amendment","86th Amendment"],"answer":1,"explanation":"The 44th Amendment (1978) removed it; it is now a constitutional legal right under Article 300A.","difficulty":"hard"},
  {"id":"polity-fundamental-rights-7","question":"Which writ directs a public official to perform a duty they have failed to perform?","options":["Habeas Corpus","Mandamus","Certiorari","Quo Warranto"],"answer":1,"explanation":"Mandamus (“we command”) orders a public authority to do its duty.","difficulty":"hard"},
  {"id":"polity-fundamental-rights-8","question":"The writ of Quo Warranto is issued to:","options":["Order the release of a person from unlawful detention","Test a person's legal claim to hold a public office","Quash an order already passed by an inferior court","Stop an inferior court from exceeding its jurisdiction"],"answer":1,"explanation":"Quo Warranto (“by what authority”) challenges a person’s claim to a public office.","difficulty":"hard"},
  {"id":"polity-fundamental-rights-9","question":"Which Fundamental Right is available to citizens only, not to foreigners?","options":["Article 14","Article 19","Article 21","Article 25"],"answer":1,"explanation":"Article 19 (six freedoms) is for citizens only; Articles 14, 21 and 25 apply to all persons.","difficulty":"very-hard"},
  {"id":"polity-fundamental-rights-10","question":"Which Fundamental Rights cannot be suspended even during a National Emergency?","options":["Articles 14 and 19","Articles 19 and 32","Articles 20 and 21","Articles 25 and 26"],"answer":2,"explanation":"After the 44th Amendment, Articles 20 and 21 cannot be suspended under Article 359.","difficulty":"very-hard"},
  {"id":"polity-fundamental-rights-11","question":"Under which Article can Parliament restrict the Fundamental Rights of members of the armed forces?","options":["Article 33","Article 34","Article 35","Article 31"],"answer":0,"explanation":"Article 33 empowers Parliament to modify Fundamental Rights for armed forces, police and intelligence agencies.","difficulty":"very-hard"},
  {"id":"polity-fundamental-rights-12","question":"Which Article of the Constitution abolishes untouchability?","options":["Article 14","Article 15","Article 17","Article 21"],"answer":2,"explanation":"Article 17 abolishes untouchability and forbids its practice in any form.","difficulty":"easy","source":"SSC CGL · RRB NTPC"},
  {"id":"polity-fundamental-rights-13","question":"Which Article is called the “heart and soul of the Constitution” (right to constitutional remedies)?","options":["Article 19","Article 21","Article 32","Article 226"],"answer":2,"explanation":"Ambedkar called Article 32 the heart and soul of the Constitution.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims"},
  {"id":"polity-fundamental-rights-14","question":"The writ issued to a person holding a public office to show by what authority they hold it is:","options":["Habeas corpus","Mandamus","Certiorari","Quo warranto"],"answer":3,"explanation":"Quo warranto means “by what warrant”: it asks the holder of a substantive public office to show his legal authority. Mandamus commands a public duty to be performed, and certiorari quashes an order already made, so neither tests title to an office.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"polity-fundamental-rights-15","question":"The right to property was removed from the Fundamental Rights by the 44th Amendment and placed as a legal right under:","options":["Article 19(1)(f)","Article 31","Article 300A","Article 350"],"answer":2,"explanation":"Since 1978 Article 300A protects property as a constitutional, not fundamental, right.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL"},
  {"id":"polity-fundamental-rights-16","question":"Consider: 1. Article 15 is available only to citizens. 2. Article 21 is available to citizens and foreigners. 3. Article 19 is suspended automatically during an emergency declared on the ground of war or external aggression. Which are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":3,"explanation":"All three are correct. Since the 44th Amendment, Article 358 suspends Article 19 only for war or external aggression, not armed rebellion.","difficulty":"hard"},
  {"id":"polity-fundamental-rights-17","question":"Employment of children below 14 years in factories, mines or other hazardous work is prohibited by:","options":["Article 21A","Article 23","Article 24","Article 39"],"answer":2,"explanation":"Article 24 bans child labour in hazardous jobs; Article 23 bans forced labour and trafficking.","difficulty":"hard"},
  {"id":"polity-fundamental-rights-18","question":"During a National Emergency, the President cannot suspend the right to move courts for the enforcement of:","options":["Articles 14 and 19","Articles 19 and 21","Articles 20 and 21","Articles 21 and 32"],"answer":2,"explanation":"The 44th Amendment (1978) made Articles 20 and 21 non-suspendable under Article 359.","difficulty":"very-hard"},
  {"id":"polity-fundamental-rights-19","question":"The right to privacy was held to be a fundamental right by a nine-judge bench in:","options":["Maneka Gandhi v Union of India (1978)","K. S. Puttaswamy v Union of India (2017)","A. K. Gopalan v State of Madras (1950)","Kharak Singh v State of Uttar Pradesh (1962)"],"answer":1,"explanation":"Puttaswamy (2017) held privacy to be intrinsic to Article 21, overruling the earlier view in M. P. Sharma and Kharak Singh.","difficulty":"very-hard"},
  {"id":"polity-fundamental-rights-20","question":"How many of these statements are correct? I. Article 14 applies to all persons, including foreigners. II. Article 16 deals with equality of opportunity in public employment. III. Article 18 bars titles but allows military and academic distinctions. IV. Article 17 can be enforced only against the State.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Article 17 (untouchability) applies against private persons too.","difficulty":"very-hard"},
  {"id":"polity-fundamental-rights-21","question":"How many of these statements are correct? I. Habeas corpus can be issued against private individuals. II. Mandamus can be issued against the President. III. Prohibition can be issued against purely administrative authorities.","options":["Only one","Only two","All three","None"],"answer":0,"explanation":"Only I. Mandamus does not lie against the President or a Governor, and prohibition lies only against judicial or quasi-judicial bodies.","difficulty":"very-hard"},
  {"id":"polity-fundamental-rights-22","question":"How many of these Articles are available to foreigners as well as citizens? I. Article 14 II. Article 15 III. Article 20 IV. Article 29","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only Articles 14 and 20. Article 15 protects citizens only, and Article 29 protects “any section of the citizens”.","difficulty":"very-hard"},
  {"id":"polity-fundamental-rights-23","question":"How many of these statements are correct? I. Article 32 is itself a fundamental right. II. The writ jurisdiction of the Supreme Court under Article 32 is wider than that of High Courts under Article 226. III. Jawaharlal Nehru called Article 32 the “heart and soul” of the Constitution.","options":["Only one","Only two","All three","None"],"answer":0,"explanation":"Only I is correct. Article 226 is wider, since High Courts can issue writs for any legal right, not only fundamental rights; and it was Dr Ambedkar, not Nehru, who called Article 32 the 'heart and soul' of the Constitution.","difficulty":"very-hard"},
  {"id":"polity-fundamental-rights-24","question":"The “doctrine of eclipse” applies to:","options":["Pre-Constitution laws inconsistent with fundamental rights","Post-Constitution laws that violate fundamental rights","Constitutional amendments that violate the basic structure","Ordinances that lapse six weeks after Parliament reassembles"],"answer":0,"explanation":"A pre-1950 law that conflicts with a fundamental right is not void but eclipsed; it revives if the right is amended (Bhikaji Narain Dhakras, 1955). Post-constitutional laws that violate fundamental rights are void from the start.","difficulty":"very-hard"},
  {"id":"polity-fundamental-rights-25","question":"Which pair of writ and its literal meaning is NOT correctly matched?","options":["Habeas corpus – “to have the body”","Mandamus – “we command”","Certiorari – “to be certified”","Quo warranto – “to forbid”"],"answer":3,"explanation":"Quo warranto means “by what authority”; it is prohibition that means “to forbid”.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL"},
  {"id":"polity-fundamental-rights-26","question":"How many of these statements are correct? I. Article 19 originally guaranteed seven freedoms; the right to property was dropped by the 44th Amendment. II. The safeguards of Article 22 against arrest do not apply to enemy aliens. III. Preventive detention beyond three months needs the opinion of an advisory board. IV. Article 21 can be suspended by a Presidential order under Article 359.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Since the 44th Amendment, Articles 20 and 21 cannot be suspended even during a National Emergency.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-27", "question": "The Right to Freedom of Religion is guaranteed by which Articles of the Constitution?", "options": ["Articles 19 to 22", "Articles 23 and 24", "Articles 25 to 28", "Articles 29 and 30"], "answer": 2, "explanation": "Articles 25–28 cover freedom of conscience, management of religious affairs, freedom from religious taxes and freedom from religious instruction in state institutions. Articles 29–30 are the Cultural and Educational Rights.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-fundamental-rights-28", "question": "Protection against double jeopardy and against being compelled to be a witness against oneself is given by:", "options": ["Article 20", "Article 21", "Article 22", "Article 19"], "answer": 0, "explanation": "Article 20 gives three protections in respect of conviction for offences: no ex post facto law, no double jeopardy and no self-incrimination. Article 22 deals with arrest and detention.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC"},
  {"id": "polity-fundamental-rights-29", "question": "The Cultural and Educational Rights of minorities are contained in:", "options": ["Articles 14 and 15", "Articles 23 and 24", "Articles 25 and 26", "Articles 29 and 30"], "answer": 3, "explanation": "Article 29 protects the language, script and culture of any section of citizens, and Article 30 gives minorities the right to establish and administer educational institutions.", "difficulty": "easy", "source": "SSC CGL · UPSSSC PET"},
  {"id": "polity-fundamental-rights-30", "question": "Under which clause of Article 15 can the State make special provisions for women and children?", "options": ["Article 15(2)", "Article 15(5)", "Article 15(4)", "Article 15(3)"], "answer": 3, "explanation": "Article 15(3) allows special provisions for women and children. Article 15(4) (added in 1951) covers socially and educationally backward classes, SCs and STs, and 15(5) their admission to private educational institutions.", "difficulty": "moderate", "source": "SSC CGL · UPSC Prelims"},
  {"id": "polity-fundamental-rights-31", "question": "Which provision permits reservation of posts in favour of a backward class of citizens that is not adequately represented in state services?", "options": ["Article 16(1)", "Article 16(2)", "Article 16(4)", "Article 16(3)"], "answer": 2, "explanation": "Article 16(4) enables reservation in appointments for any backward class not adequately represented in the services. Article 16(3) lets Parliament prescribe residence as a condition for certain posts.", "difficulty": "moderate", "source": "SSC CGL · UPSC Prelims"},
  {"id":"polity-fundamental-rights-32","question":"Article 23 prohibits traffic in human beings and begar, but it expressly allows the State to:","options":["Employ children in non-hazardous work with a guardian's consent","Impose compulsory service for public purposes without discrimination","Permit bonded labour in agriculture until an existing debt is repaid","Levy a tax in place of military service on those who are exempted"],"answer":1,"explanation":"Article 23(2) lets the State impose compulsory service for public purposes (such as military or social service) provided it does not discriminate on grounds of religion, race, caste or class.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-33", "question": "Article 30 gives the right to establish and administer educational institutions to:", "options": ["All citizens", "Religious and linguistic minorities", "Scheduled Castes and Scheduled Tribes", "Only religious minorities"], "answer": 1, "explanation": "Article 30(1) confers the right on all minorities, whether based on religion or language. It is a group right that is not available to the majority community.", "difficulty": "moderate", "source": "SSC CGL · UPSC Prelims"},
  {"id": "polity-fundamental-rights-34", "question": "Which of these is NOT a ground on which the State may impose reasonable restrictions on freedom of speech under Article 19(2)?", "options": ["Sovereignty and integrity of India", "Contempt of court", "Defamation", "Economic interests of the State"], "answer": 3, "explanation": "Article 19(2) lists sovereignty and integrity, security of the State, friendly relations with foreign states, public order, decency or morality, contempt of court, defamation and incitement to an offence. Economic interests are not a ground.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-35", "question": "Article 13 declares laws inconsistent with Fundamental Rights void “to the extent of such inconsistency”. The doctrine that follows from these words is the doctrine of:", "options": ["Eclipse", "Severability", "Waiver", "Pith and substance"], "answer": 1, "explanation": "Under the doctrine of severability only the offending part of a law is struck down, if it can be separated from the rest. The doctrine of eclipse applies to pre-constitutional laws that become dormant, not dead.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-fundamental-rights-36", "question": "Which Amendment added clause (4) to Article 13, declaring that a constitutional amendment under Article 368 is not “law” for the purposes of Article 13?", "options": ["1st Amendment, 1951", "24th Amendment, 1971", "25th Amendment, 1971", "42nd Amendment, 1976"], "answer": 1, "explanation": "After Golaknath (1967) held that Parliament could not amend Fundamental Rights, the 24th Amendment added Article 13(4) and Article 368(3) to restore the amending power. The 25th Amendment inserted Article 31C.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-fundamental-rights-37", "question": "Article 15(5), which allows reservation for socially and educationally backward classes in private unaided educational institutions other than minority institutions, was inserted by the:", "options": ["85th Amendment, 2001", "86th Amendment, 2002", "93rd Amendment, 2005", "97th Amendment, 2011"], "answer": 2, "explanation": "The 93rd Amendment (2005) added Article 15(5) after the Supreme Court’s decision in P. A. Inamdar; it excludes minority institutions under Article 30(1). The 86th Amendment added Article 21A.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-38", "question": "The 10% reservation for Economically Weaker Sections was added through Articles 15(6) and 16(6) by the:", "options": ["102nd Amendment, 2018", "103rd Amendment, 2019", "104th Amendment, 2019", "101st Amendment, 2016"], "answer": 1, "explanation": "The 103rd Amendment (2019) inserted Articles 15(6) and 16(6); it was upheld by a 3:2 majority in Janhit Abhiyan v. Union of India (2022). The 102nd Amendment gave constitutional status to the National Commission for Backward Classes.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-39", "question": "Before Article 21A was inserted in 2002, the Supreme Court had already read a right to education for children up to 14 years into Article 21 in:", "options": ["Vishaka v. State of Rajasthan (1997)", "Maneka Gandhi v. Union of India (1978)", "Olga Tellis v. Bombay Municipal Corporation (1985)", "Unni Krishnan v. State of Andhra Pradesh (1993)"], "answer": 3, "explanation": "In Unni Krishnan (1993), building on Mohini Jain (1992), the Court held that the right to education up to 14 years flows from Article 21 read with Article 45. Olga Tellis dealt with the right to livelihood and Vishaka with sexual harassment at work.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id":"polity-fundamental-rights-40","question":"The 44th Amendment (1978) reduced the period for which a person can be preventively detained without the opinion of an advisory board from three months to two months. What is the status of this change?","options":["It has been in force since the Amendment was notified in 1979","It was struck down by the Supreme Court in A. K. Roy (1982)","It was never notified, so the three-month limit still applies","It applies only to detentions under central laws such as the NSA"],"answer":2,"explanation":"Section 3 of the 44th Amendment Act, which amended Article 22, was never notified by the government, so the original three-month limit continues to operate.","difficulty":"hard","source":"UPSC Prelims · State PSC"},
  {"id": "polity-fundamental-rights-41", "question": "The narrow interpretation of “procedure established by law” in A. K. Gopalan (1950) was overturned, requiring the procedure under Article 21 to be just, fair and reasonable, in:", "options": ["Kharak Singh v. State of U.P. (1962)", "Sunil Batra v. Delhi Administration (1978)", "ADM Jabalpur v. Shivkant Shukla (1976)", "Maneka Gandhi v. Union of India (1978)"], "answer": 3, "explanation": "Maneka Gandhi (1978) read Articles 14, 19 and 21 together and introduced American-style due process into Article 21. ADM Jabalpur (the Habeas Corpus case) had, in contrast, denied relief during the Emergency.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-42", "question": "The right to form co-operative societies was added to Article 19(1)(c) by the:", "options": ["73rd Amendment, 1992", "86th Amendment, 2002", "97th Amendment, 2011", "99th Amendment, 2014"], "answer": 2, "explanation": "The 97th Amendment (2011) added “co-operative societies” to Article 19(1)(c), inserted Article 43B in the Directive Principles and added Part IX-B on co-operative societies.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-43", "question": "Under Article 32(3), the power to issue writs for the enforcement of Fundamental Rights can be conferred on any other court by:", "options": ["The President by order", "Parliament by law", "The Supreme Court by rules", "The Chief Justice of India"], "answer": 1, "explanation": "Article 32(3) empowers Parliament, by law, to authorise any other court to exercise the Supreme Court’s writ powers without prejudice to the Supreme Court’s own jurisdiction. No such law has yet been made.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-fundamental-rights-44", "question": "The protection against ex post facto laws in Article 20(1) does NOT extend to:", "options": ["Imposing a penalty greater than that prescribed when the offence was committed", "Conviction for an act that was not an offence when committed", "Civil liabilities and retrospective tax laws", "Punishment for a criminal offence under a retrospective law"], "answer": 2, "explanation": "Article 20(1) applies only to criminal convictions and punishments. Civil legislation and tax laws can operate retrospectively, as can preventive detention, which is not a punishment for an offence.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id":"polity-fundamental-rights-45","question":"How many of these statements about Article 19 are correct? I. Article 19 today guarantees six freedoms. II. The freedom to acquire, hold and dispose of property under Article 19(1)(f) was deleted by the 44th Amendment. III. The ground “sovereignty and integrity of India” in Article 19(2) was added by the 16th Amendment, 1963. IV. The rights under Article 19 are available only to citizens.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: Article 19 now has six freedoms after the 44th Amendment removed 19(1)(f), the 16th Amendment (1963) added 'sovereignty and integrity of India', and Article 19 rights are available only to citizens.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-46", "question": "Assertion (A): The rights under Articles 20 and 21 cannot be suspended even during a National Emergency. Reason (R): The 44th Amendment, 1978 amended Article 359 to exclude Articles 20 and 21 from any Presidential order suspending the enforcement of Fundamental Rights.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "After the Emergency experience and ADM Jabalpur, the 44th Amendment made Articles 20 and 21 immune from suspension under Article 359; R is exactly why A holds.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-47", "question": "Arrange these Supreme Court cases in chronological order: 1. Maneka Gandhi 2. A. K. Gopalan 3. K. S. Puttaswamy 4. Kesavananda Bharati", "options": ["2, 4, 1, 3", "2, 1, 4, 3", "4, 2, 1, 3", "2, 4, 3, 1"], "answer": 0, "explanation": "A. K. Gopalan (1950), Kesavananda Bharati (1973), Maneka Gandhi (1978) and Puttaswamy (2017).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-fundamental-rights-48", "question": "Which pair of Article and its subject is NOT correctly matched?", "options": ["Article 16 – Equality of opportunity in public employment", "Article 18 – Abolition of untouchability", "Article 23 – Prohibition of traffic in human beings and forced labour", "Article 28 – Freedom from religious instruction in institutions wholly maintained by State funds"], "answer": 1, "explanation": "Article 18 abolishes titles; untouchability is abolished by Article 17.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-fundamental-rights-49", "question": "How many of these statements about Articles 25 to 28 are correct? I. Article 25 (freedom of conscience) is available to all persons, not only citizens. II. Article 26 gives rights to religious denominations as groups. III. Article 27 says no person shall be compelled to pay taxes for the promotion of any particular religion. IV. Article 28 bars religious instruction in institutions wholly maintained out of State funds.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Note the distinction in Article 27: a tax for promoting a religion is barred, but a fee for regulating religious institutions is permissible.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-fundamental-rights-50", "question": "How many of these statements about reservation-related Amendments are correct? I. The 77th Amendment (1995) added Article 16(4A) allowing reservation in promotions for SCs and STs. II. The 81st Amendment (2000) added Article 16(4B) allowing unfilled reserved vacancies to be carried forward. III. The 85th Amendment (2001) introduced the “creamy layer” concept into Article 16. IV. The 103rd Amendment (2019) added Articles 15(6) and 16(6) for Economically Weaker Sections.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV are correct. The 85th Amendment gave consequential seniority in promotion; the creamy layer idea came from the Supreme Court (Indra Sawhney, 1992), not from an amendment.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-fundamental-rights-51", "question": "Assertion (A): Some Fundamental Rights can be enforced against private individuals and not only against the State. Reason (R): Articles 15(2), 17, 23 and 24 are worded so as to apply against private persons as well.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Most Fundamental Rights run against the State, but access to shops and public places (15(2)), untouchability (17), forced labour (23) and child labour (24) are enforceable against private persons too.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id":"polity-fundamental-rights-52","question":"How many of these statements about writs are correct? I. Habeas corpus will not be issued when the detention is lawful. II. Mandamus cannot be issued to enforce a private contractual obligation. III. Certiorari, originally confined to judicial and quasi-judicial bodies, has been available against administrative authorities since 1991. IV. Quo warranto lies only in respect of a substantive public office.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Habeas corpus fails for lawful detention, mandamus does not enforce private contracts, certiorari extends to administrative authorities since 1991, and quo warranto lies only for a substantive public office.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL"},
  {"id":"polity-fundamental-rights-53","question":"Arrange these Constitutional Amendments in chronological order: 1. 44th Amendment (right to property removed) 2. 86th Amendment (right to education) 3. 24th Amendment (Article 13(4) added) 4. 93rd Amendment (Article 15(5) added)","options":["3, 1, 2, 4","1, 3, 2, 4","3, 1, 4, 2","1, 3, 4, 2"],"answer":0,"explanation":"Anchor each amendment to its year: 24th (1971), 44th (1978), 86th (2002) and 93rd (2005), giving 3, 1, 2, 4. The tempting slip is placing the 93rd before the 86th because both deal with education.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id": "polity-fundamental-rights-54", "question": "How many of these have been held by the Supreme Court to be part of the right to life under Article 21? I. Right to sleep II. Right to die with dignity, including passive euthanasia III. Right to privacy IV. Right to property", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I (Ramlila Maidan, 2012), II (Common Cause, 2018) and III (Puttaswamy, 2017) are part of Article 21. The right to property is only a constitutional/legal right under Article 300A since 1978.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-fundamental-rights-55", "question": "Which of these is NOT a Fundamental Right under Article 19?", "options": ["Right to form associations or unions", "Right to strike", "Right to move freely throughout the territory of India", "Right to reside and settle in any part of India"], "answer": 1, "explanation": "The Supreme Court has repeatedly held that the right to strike is not a fundamental right; it is only a legal right regulated by industrial law, and does not flow from the right to form unions under Article 19(1)(c).", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-56", "question": "Assertion (A): Article 15(4), permitting special provisions for socially and educationally backward classes, was added by the 1st Amendment, 1951. Reason (R): It was Parliament’s response to the Supreme Court striking down caste-based reservation in State of Madras v. Champakam Dorairajan.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "In Champakam Dorairajan (1951) the Court struck down the Madras Communal G.O. as violating Article 15(1); the 1st Amendment then inserted Article 15(4) to permit such provisions.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-fundamental-rights-57", "question": "Article 21A obliges the State to provide free and compulsory education to all children in the age group of:", "options": ["3 to 10 years", "5 to 15 years", "6 to 14 years", "6 to 18 years"], "answer": 2, "explanation": "Article 21A, inserted by the 86th Amendment (2002), covers children aged six to fourteen; the Right of Children to Free and Compulsory Education Act, 2009 gives it effect.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "polity-fundamental-rights-58", "question": "Which Article defines the term “State” for the purposes of Part III (Fundamental Rights)?", "options": ["Article 12", "Article 13", "Article 36", "Article 14"], "answer": 0, "explanation": "Article 12 defines “State” to include the Government and Parliament of India, State governments and legislatures, and all local or other authorities. Article 36 applies the same meaning to Part IV.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "polity-fundamental-rights-59", "question": "Under Article 22(2), a person arrested and detained must be produced before the nearest magistrate within:", "options": ["12 hours", "24 hours, excluding the time of the journey", "48 hours, including the time of the journey", "72 hours"], "answer": 1, "explanation": "Article 22(2) fixes 24 hours, excluding the time needed for the journey from the place of arrest to the court. No further detention is allowed without the magistrate’s authority.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "polity-fundamental-rights-60", "question": "The freedom to reside and settle in any part of the territory of India is guaranteed by:", "options": ["Article 19(1)(b)", "Article 19(1)(d)", "Article 19(1)(g)", "Article 19(1)(e)"], "answer": 3, "explanation": "Article 19(1)(e) is the freedom to reside and settle; 19(1)(d) is the separate freedom to move freely throughout India; 19(1)(b) is to assemble peaceably and 19(1)(g) is to practise any profession or trade.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "polity-fundamental-rights-61", "question": "The Ninth Schedule, which shields the laws placed in it from challenge on the ground of violating Fundamental Rights, was added along with Article 31B by the:", "options": ["1st Amendment, 1951", "4th Amendment, 1955", "17th Amendment, 1964", "25th Amendment, 1971"], "answer": 0, "explanation": "The 1st Amendment (1951) created Article 31B and the Ninth Schedule to protect land reform laws. In I. R. Coelho (2007) the Court held that laws added after 24 April 1973 can still be tested against the basic structure.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id":"polity-fundamental-rights-62","question":"Article 29(1), which protects the right to conserve a distinct language, script or culture, is available to:","options":["Only religious minorities notified as such by the Central Government","Only linguistic minorities, as determined State by State","Any section of citizens with its own language, script or culture","All persons residing in India, including foreign nationals"],"answer":2,"explanation":"Article 29(1) speaks of “any section of the citizens”, so it is not confined to minorities, unlike Article 30. Being limited to citizens, it does not extend to foreigners.","difficulty":"moderate","source":"UPSC Prelims · State PSC"},
  {"id": "polity-fundamental-rights-63", "question": "Explanation I to Article 25 states that the wearing and carrying of which of these shall be deemed to be included in the profession of the Sikh religion?", "options": ["Kara", "Kirpan", "Kesh", "Kangha"], "answer": 1, "explanation": "Explanation I to Article 25 expressly protects the wearing and carrying of kirpans by Sikhs. The other articles of faith are not mentioned in the text.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "polity-fundamental-rights-64", "question": "Under Article 16(3), a residence requirement within a State for appointment to certain posts under that State can be prescribed only by:", "options": ["The State Legislature", "The Governor", "Parliament", "The State Public Service Commission"], "answer": 2, "explanation": "Article 16(3) allows only Parliament to prescribe residence as a condition for employment in a State; Article 35 reinforces that such laws are for Parliament alone, not State legislatures.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-65", "question": "Under Article 35, the power to make laws to give effect to provisions such as Articles 16(3), 32(3), 33 and 34 is vested in:", "options": ["Parliament only", "State Legislatures only", "Both Parliament and State Legislatures", "The President by order"], "answer": 0, "explanation": "Article 35 gives this power exclusively to Parliament so that there is uniformity across India; State legislatures cannot legislate on these matters.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-66", "question": "Article 34 allows Parliament, by law, to indemnify any government servant for acts done to restore order in an area where:", "options": ["A National Emergency is in force", "Martial law was in force", "President’s Rule is in force", "An area is declared disturbed under AFSPA"], "answer": 1, "explanation": "Article 34 deals with restriction of rights while martial law is in force, and lets Parliament indemnify acts done in connection with it. The Constitution does not define martial law.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id":"polity-fundamental-rights-67","question":"In Indra Sawhney v. Union of India (1992), the Supreme Court upheld 27% reservation for OBCs subject to which conditions?","options":["Exclusion of the creamy layer and an overall ceiling of 50%","Reservation in promotions and no fixed ceiling on the total","A 60% ceiling and identification on economic criteria alone","Reservation confined to backward classes among Hindus only"],"answer":0,"explanation":"The nine-judge bench required the creamy layer to be excluded, set a normal 50% ceiling and held that Article 16(4) does not permit reservation in promotions (later restored for SCs/STs by the 77th Amendment).","difficulty":"hard","source":"UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-68", "question": "The right to a speedy trial was first recognised as part of Article 21 in:", "options": ["Hussainara Khatoon v. State of Bihar (1979)", "Olga Tellis v. Bombay Municipal Corporation (1985)", "Maneka Gandhi v. Union of India (1978)", "Sunil Batra v. Delhi Administration (1978)"], "answer": 0, "explanation": "Hussainara Khatoon, a PIL on undertrial prisoners in Bihar, held speedy trial to be implicit in Article 21. Olga Tellis concerned pavement dwellers and the right to livelihood.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-69", "question": "The Supreme Court held that the right to livelihood is part of the right to life under Article 21 in a case brought by pavement dwellers of Bombay. The case is:", "options": ["M. C. Mehta v. Union of India", "Olga Tellis v. Bombay Municipal Corporation", "Vishaka v. State of Rajasthan", "Francis Coralie Mullin v. Administrator, Delhi"], "answer": 1, "explanation": "Olga Tellis (1985) held that eviction deprives a person of livelihood and therefore engages Article 21, though it allowed eviction after fair procedure. Vishaka (1997) laid down guidelines on sexual harassment at work.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id":"polity-fundamental-rights-70","question":"Which of these has been held by the Supreme Court NOT to be “State” under Article 12?","options":["Life Insurance Corporation of India","Oil and Natural Gas Corporation Ltd","A municipal corporation of a large city","Board of Control for Cricket in India"],"answer":3,"explanation":"In Zee Telefilms v. Union of India (2005) the Court held the BCCI is not “State” since it is not financially, functionally or administratively controlled by the government; it remains subject to writs under Article 226 for public functions. Statutory corporations such as LIC and ONGC are State.","difficulty":"hard","source":"UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-71", "question": "Match the case with what it decided: A. Shreya Singhal (2015) B. Navtej Singh Johar (2018) C. Selvi v. State of Karnataka (2010) D. Shayara Bano (2017). 1. Instant triple talaq is unconstitutional 2. Section 66A of the IT Act struck down 3. Consensual same-sex relations between adults decriminalised 4. Involuntary narco-analysis violates Article 20(3)", "options": ["A-2, B-3, C-1, D-4", "A-3, B-2, C-4, D-1", "A-2, B-3, C-4, D-1", "A-4, B-3, C-2, D-1"], "answer": 2, "explanation": "Shreya Singhal struck down Section 66A as violating Article 19(1)(a); Navtej Johar read down Section 377 IPC; Selvi held compulsory narco tests violate the right against self-incrimination; Shayara Bano invalidated talaq-e-biddat.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-72", "question": "How many of these statements about Article 22 are correct? I. An arrested person must be informed of the grounds of arrest as soon as may be. II. An arrested person has the right to consult and be defended by a legal practitioner of choice. III. An arrested person must be produced before a magistrate within 24 hours. IV. These three safeguards apply equally to a person held under a preventive detention law.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct under Article 22(1) and (2). IV is wrong: Article 22(3) expressly excludes enemy aliens and persons under preventive detention from these safeguards; detainees get the separate protections of 22(4)–(7).", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-73", "question": "Assertion (A): The freedoms under Article 19 are automatically suspended when a National Emergency is proclaimed on the ground of armed rebellion. Reason (R): After the 44th Amendment, Article 358 suspends Article 19 only when the Emergency is declared on the ground of war or external aggression.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 3, "explanation": "A is false and R is true. Since 1978, Article 358 applies only to an external Emergency (war or external aggression); an Emergency on the ground of armed rebellion does not automatically suspend Article 19.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-74", "question": "Arrange these cases on Parliament’s power to amend Fundamental Rights in chronological order: 1. Golaknath 2. Shankari Prasad 3. Sajjan Singh 4. Kesavananda Bharati", "options": ["2, 1, 3, 4", "2, 3, 1, 4", "3, 2, 1, 4", "2, 3, 4, 1"], "answer": 1, "explanation": "Shankari Prasad (1951) and Sajjan Singh (1965) upheld Parliament’s power to amend Fundamental Rights; Golaknath (1967) denied it; Kesavananda Bharati (1973) restored it subject to the basic structure.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id":"polity-fundamental-rights-75","question":"How many of these statements about Article 30 are correct? I. Minority status for Article 30 is determined State-wise, as held in T. M. A. Pai Foundation (2002). II. Article 30(1A), on compensation when the property of a minority institution is acquired, was added by the 44th Amendment. III. The State cannot discriminate against a minority institution while granting aid. IV. Article 30 is available to both religious and linguistic minorities.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: TMA Pai (2002) made minority status State-wise, Article 30(1A) came from the 44th Amendment, Article 30(2) bars discrimination in aid, and Article 30(1) covers minorities based on religion or language.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL"},
  {"id":"polity-fundamental-rights-76","question":"How many of these are grounds on which reasonable restrictions may be imposed on freedom of speech and expression under Article 19(2)? I. Contempt of court II. Defamation III. Protection of the interests of any Scheduled Tribe IV. Interests of the general public","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are grounds in Article 19(2). Protection of Scheduled Tribes' interests is a ground under Article 19(5) for movement and residence, and interests of the general public is a ground under Articles 19(5) and 19(6), not for speech.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-77", "question": "How many of these statements about Article 17 are correct? I. The Untouchability (Offences) Act, 1955 was renamed the Protection of Civil Rights Act in 1976. II. The Constitution does not define “untouchability”. III. The SC and ST (Prevention of Atrocities) Act was enacted in 1989. IV. The right under Article 17 is absolute and not subject to any exception.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Article 17 abolishes untouchability and forbids its practice in any form, without exceptions, and leaves the term undefined; Parliament has enforced it through the 1955 (renamed 1976) and 1989 Acts.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-fundamental-rights-78", "question": "How many of these statements about Articles 15 and 16 are correct? I. Article 15(1) bars discrimination on grounds only of religion, race, caste, sex or place of birth. II. Article 16(2) additionally lists descent and residence as forbidden grounds in public employment. III. Article 15(2) applies to access to shops, hotels and places of public entertainment, even when privately owned. IV. Article 16(5) permits an office connected with a religious institution to be reserved for members of that religion.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Descent and residence appear in Article 16(2) but not in Article 15(1), a frequent trap; 15(2) binds private persons too.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-79", "question": "Assertion (A): The protection against double jeopardy under Article 20(2) does not bar departmental proceedings after a criminal prosecution for the same act. Reason (R): Article 20(2) applies only where the person has been prosecuted and punished before a court or judicial tribunal.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A. As held in Maqbool Hussain (1953), departmental or administrative proceedings are not prosecution and punishment by a court, so Article 20(2) does not apply to them.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-fundamental-rights-80", "question": "Arrange these insertions into Part III in chronological order: 1. Article 15(4) for backward classes 2. Article 16(4A) for reservation in promotions 3. The right to form co-operative societies in Article 19(1)(c) 4. Article 21A", "options": ["1, 2, 4, 3", "1, 4, 2, 3", "2, 1, 4, 3", "1, 2, 3, 4"], "answer": 0, "explanation": "Article 15(4): 1st Amendment, 1951. Article 16(4A): 77th Amendment, 1995. Article 21A: 86th Amendment, 2002. Co-operative societies: 97th Amendment, 2011.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-81", "question": "Which of these Fundamental Rights is available ONLY to citizens and not to foreigners?", "options": ["Article 20 – protection in respect of conviction for offences", "Article 22 – protection against arbitrary arrest", "Article 25 – freedom of religion", "Article 16 – equality of opportunity in public employment"], "answer": 3, "explanation": "Articles 15, 16, 19, 29 and 30 are confined to citizens. Articles 20, 21, 22 and 25 extend to all persons, though Article 22’s safeguards do not apply to enemy aliens.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "polity-fundamental-rights-82", "question": "The phrase \"equal protection of the laws\" in Article 14 is drawn from the Constitution of:", "options": ["Britain", "USA", "Ireland", "Canada"], "answer": 1, "explanation": "Article 14 combines \"equality before the law\", a British idea (a negative concept: no special privileges), with \"equal protection of the laws\", taken from the 14th Amendment of the US Constitution (a positive concept: like treatment in like circumstances).", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id":"polity-fundamental-rights-83","question":"The right to vote in elections to the Lok Sabha and State Assemblies is a:","options":["A Fundamental Right under Article 21","A Fundamental Right guaranteed by Article 326","A Fundamental Duty under Article 51A","A constitutional and statutory right only"],"answer":3,"explanation":"Article 326 provides for adult suffrage, and the details are in the Representation of the People Act, 1951. Voting is therefore a constitutional and statutory right, not a Fundamental Right, as the Supreme Court has held several times (for example in Kuldip Nayar, 2006).","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "polity-fundamental-rights-84", "question": "Freedom of the press is not mentioned in so many words in the Constitution. The Supreme Court has held it to be part of:", "options": ["Article 19(1)(a)", "Article 14", "Article 19(1)(g)", "Article 21"], "answer": 0, "explanation": "Freedom of the press is implied in the freedom of speech and expression under Article 19(1)(a), as the Court held from Romesh Thappar and Brij Bhushan (1950) onwards. Article 19(1)(g), the freedom of trade or business, is the tempting wrong option.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id":"polity-fundamental-rights-85","question":"Under Explanation II to Article 25, the reference to \"Hindus\" in Article 25(2)(b) includes persons professing which religions?","options":["Sikh, Jaina or Parsi","Sikh, Jaina or Buddhist","Buddhist, Jaina or Parsi","Sikh, Buddhist or Christian"],"answer":1,"explanation":"Explanation II says the reference to Hindus includes persons professing the Sikh, Jaina or Buddhist religion, and that Hindu religious institutions are to be read the same way. This matters for laws throwing open Hindu religious institutions to all classes.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-86", "question": "Article 19(1)(b) guarantees citizens the right to assemble. Which two conditions are written into the clause itself?", "options": ["Peaceably and without arms", "With police permission and in daylight", "In public places and with prior notice", "Without arms and for lawful purposes only"], "answer": 0, "explanation": "The clause reads \"to assemble peaceably and without arms\". Other limits, such as public order and the sovereignty and integrity of India, come through Article 19(3), not through the clause itself.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "polity-fundamental-rights-87", "question": "The concept of \"rule of law\", which is reflected in \"equality before the law\" in Article 14, was propounded by:", "options": ["Ivor Jennings", "Ernest Barker", "K. C. Wheare", "A. V. Dicey"], "answer": 3, "explanation": "A. V. Dicey set out the rule of law with three parts: no arbitrary power, equality before the law, and the primacy of individual rights. The Supreme Court has held the rule of law to be a basic feature of the Constitution.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-88", "question": "The Vishaka guidelines (1997) on sexual harassment of women at the workplace, based on Articles 14, 15, 19(1)(g) and 21, were later replaced by a law passed in:", "options": ["2005", "2013", "2010", "2019"], "answer": 1, "explanation": "The Sexual Harassment of Women at Workplace (Prevention, Prohibition and Redressal) Act, 2013 (the POSH Act) gave statutory form to the Vishaka guidelines, including Internal Complaints Committees.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id":"polity-fundamental-rights-89","question":"In Bijoe Emmanuel v. State of Kerala (1986), the Supreme Court protected schoolchildren who stood respectfully but did not sing the National Anthem because of their faith. Their right was upheld under:","options":["Articles 14 and 15(1)","Articles 21 and 28(3)","Articles 19(1)(a) and 25","Articles 29(1) and 30(1)"],"answer":2,"explanation":"The Court held that the freedom of speech in Article 19(1)(a) includes the freedom to remain silent, and that expelling the Jehovah's Witness children also violated their freedom of religion under Article 25. Article 28(3) is about compelled attendance at religious instruction, not the anthem.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL"},
  {"id":"polity-fundamental-rights-90","question":"In National Legal Services Authority v. Union of India (2014), the Supreme Court:","options":["Recognised transgender persons as a third gender","Decriminalised consensual same-sex relations between adults","Struck down the practice of instant triple talaq","Declared the right to privacy a fundamental right"],"answer":0,"explanation":"NALSA (2014) recognised transgender persons as a third gender entitled to rights under Articles 14, 15, 16, 19 and 21. Section 377 was read down in Navtej Singh Johar (2018), and privacy came in Puttaswamy (2017).","difficulty":"moderate","source":"UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-91", "question": "Under Article 18(3), a person who is NOT a citizen of India but holds an office of profit or trust under the State can accept a title from a foreign State only with the consent of:", "options": ["The Prime Minister", "Parliament", "The President", "The Ministry of External Affairs"], "answer": 2, "explanation": "Article 18(2) flatly bars citizens from accepting foreign titles. Article 18(3) lets a non-citizen holding an office of profit or trust under the State accept one only with the President's consent, and Article 18(4) applies the same rule to presents and emoluments.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-92", "question": "The Supreme Court upheld freedom of the press against a ban on a journal's entry into Madras State in a 1950 case, which led Parliament to add \"public order\" to Article 19(2) through the 1st Amendment. The case is:", "options": ["A. K. Gopalan v. State of Madras", "Romesh Thappar v. State of Madras", "State of Madras v. Champakam Dorairajan", "Kharak Singh v. State of U.P."], "answer": 1, "explanation": "In Romesh Thappar (1950) the ban on the journal \"Cross Roads\" was struck down because \"public order\" was not then a ground in Article 19(2). The 1st Amendment (1951) added public order, friendly relations with foreign States and incitement to an offence. Champakam Dorairajan led to Article 15(4).", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-93", "question": "Which judgment first held that \"equality is antithetic to arbitrariness\", giving Article 14 a meaning beyond reasonable classification?", "options": ["State of West Bengal v. Anwar Ali Sarkar (1952)", "R. C. Cooper v. Union of India (1970)", "Indra Sawhney v. Union of India (1992)", "E. P. Royappa v. State of Tamil Nadu (1974)"], "answer": 3, "explanation": "In E. P. Royappa (1974), Justice Bhagwati wrote that equality and arbitrariness are sworn enemies, so an arbitrary act violates Article 14. Anwar Ali Sarkar (1952) applied the older test of reasonable classification.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id":"polity-fundamental-rights-94","question":"In People's Union for Democratic Rights v. Union of India (1982), about workers on the Asiad construction projects, the Supreme Court held that:","options":["Employing contract labour on public projects is barred by Article 24","Paying below the minimum wage is forced labour under Article 23","Construction workers are entitled to housing plots under Article 39(b)","Article 23 can be enforced only against the State, not contractors"],"answer":1,"explanation":"The Court held that labour given for less than the minimum wage is \"forced labour\" banned by Article 23, since economic need is a form of compulsion. Article 23 also applies against private persons.","difficulty":"hard","source":"UPSC Prelims · SSC CGL"},
  {"id":"polity-fundamental-rights-95","question":"Article 28(1) bars religious instruction in institutions wholly maintained out of State funds. Under Article 28(2), this bar does NOT apply to an institution that:","options":["Is established and administered by a religious minority under Article 30(1)","Gets State grants covering less than half of its annual expenses","Is State-run but founded under a trust that requires religious instruction","Is a university set up by a State Act with a department of theology"],"answer":2,"explanation":"Article 28(2) exempts institutions administered by the State but established under an endowment or trust requiring religious instruction. Under Article 28(3), State-recognised or State-aided institutions may give such instruction, but nobody can be made to attend without consent (or a guardian's consent for a minor).","difficulty":"hard","source":"UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-96", "question": "In Union of India v. Naveen Jindal (2004), the Supreme Court held that the right of a citizen to fly the National Flag with respect and dignity is part of:", "options": ["Article 21", "Article 51A(a) only, and is not enforceable", "Article 25", "Article 19(1)(a)"], "answer": 3, "explanation": "The Court treated flying the flag as an expression of allegiance and pride covered by Article 19(1)(a), subject to reasonable restrictions such as the Flag Code and the Prevention of Insults to National Honour Act, 1971.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id":"polity-fundamental-rights-97","question":"The right of a poor prisoner to free legal aid, including help to file an appeal, was read into Article 21 in:","options":["M. H. Hoskot v. State of Maharashtra (1978)","D. K. Basu v. State of West Bengal (1997)","Sunil Batra v. Delhi Administration (1978)","Prem Shankar Shukla v. Delhi Administration (1980)"],"answer":0,"explanation":"M. H. Hoskot (1978) held that free legal aid for an indigent prisoner, including a free copy of the judgment and counsel for the appeal, is part of the fair procedure Article 21 requires. D. K. Basu laid down arrest guidelines and Prem Shankar Shukla dealt with handcuffing.","difficulty":"hard","source":"UPSC Prelims · SSC CGL"},
  {"id":"polity-fundamental-rights-98","question":"In Ajay Hasia v. Khalid Mujib (1981), the Supreme Court set out tests for deciding when a body is an \"instrumentality or agency of the State\" and so \"State\" under Article 12. On these tests it held which body to be \"State\"?","options":["A private cricket club affiliated to a State body","A society running a regional engineering college","A registered political party contesting elections","A private trust running a temple with public donations"],"answer":1,"explanation":"The Court held the society that ran the Regional Engineering College, Srinagar to be State, because of deep government funding and control. The tests are government share capital, financial aid, deep and pervasive control, and public functions.","difficulty":"hard","source":"UPSC Prelims · State PSCs"},
  {"id": "polity-fundamental-rights-99", "question": "Which clause of Article 16 permits a law requiring that the holder of an office connected with a religious or denominational institution belong to that religion?", "options": ["Article 16(2)", "Article 16(3)", "Article 16(5)", "Article 16(4B)"], "answer": 2, "explanation": "Article 16(5) saves such laws from the guarantee of equal opportunity. Article 16(3) concerns residence requirements, and Article 16(4B) lets unfilled reserved vacancies be carried forward.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id":"polity-fundamental-rights-100","question":"Under Article 13(3)(a), \"law\" includes several things. How many of these are covered? I. Ordinance II. Bye-law III. Custom or usage having the force of law IV. Notification","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are covered: Article 13(3)(a) defines law to include any ordinance, order, bye-law, rule, regulation, notification, and custom or usage having the force of law in India.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-101", "question": "Under Article 33, Parliament may restrict or abrogate Fundamental Rights to ensure discipline and the proper discharge of duties. How many of these groups does it cover? I. Members of the armed forces II. Members of forces charged with maintaining public order III. Persons employed in bureaus set up by the State for intelligence or counter-intelligence IV. Persons employed in telecommunication systems set up for such forces or bureaus", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are covered. Groups III and IV were added to Article 33 by the 50th Amendment (1984). Only Parliament, not a State legislature, can make such a law.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-102", "question": "Match the case with what it decided: A. Bachan Singh v. State of Punjab (1980) B. Bandhua Mukti Morcha v. Union of India (1984) C. Kaushal Kishor v. State of U.P. (2023) D. Shirur Mutt case (1954). 1. Laid the basis of the \"essential religious practices\" test 2. Death penalty only in the \"rarest of rare\" cases 3. Identifying and releasing bonded labourers 4. Rights under Articles 19 and 21 can be enforced against persons other than the State", "options": ["A-2, B-3, C-4, D-1", "A-2, B-3, C-1, D-4", "A-3, B-2, C-4, D-1", "A-2, B-4, C-3, D-1"], "answer": 0, "explanation": "Bachan Singh upheld the death penalty but limited it to the rarest of rare cases. Bandhua Mukti Morcha was a PIL on bonded labour under Articles 21 and 23. Kaushal Kishor (a Constitution Bench) held that Articles 19 and 21 can apply horizontally. The Shirur Mutt case (1954) held that Article 26 protects what is essential to a religion.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-103", "question": "Arrange these judgments in chronological order: 1. Anuradha Bhasin v. Union of India (internet shutdowns in Jammu and Kashmir) 2. Kharak Singh v. State of U.P. (night-time domiciliary visits) 3. Satwant Singh Sawhney (right to travel abroad) 4. Shreya Singhal v. Union of India (Section 66A of the IT Act)", "options": ["3, 2, 4, 1", "2, 3, 1, 4", "2, 4, 3, 1", "2, 3, 4, 1"], "answer": 3, "explanation": "Kharak Singh 1962 → Satwant Singh Sawhney 1967 → Shreya Singhal 2015 → Anuradha Bhasin 2020. Anuradha Bhasin held that speech and trade over the internet are protected under Articles 19(1)(a) and 19(1)(g), and that indefinite suspension of the internet is not permissible.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-104", "question": "Assertion (A): A citizen cannot waive a Fundamental Right, even of their own free will. Reason (R): Fundamental Rights are not only for the benefit of the individual; they rest on public policy, as the Supreme Court held in Basheshar Nath v. CIT (1959).", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "In Basheshar Nath (1959) the Court held that the rights in Part III, at least Article 14, are put there as a matter of public policy, so an individual cannot give them up by agreement or settlement. R gives the reason for A.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-105", "question": "How many of these statements about the right to education are correct? I. The Right of Children to Free and Compulsory Education Act, 2009 came into force on 1 April 2010. II. Section 12(1)(c) of the Act requires private unaided schools to admit at least 25% of the entry class from weaker and disadvantaged groups. III. In Pramati Educational and Cultural Trust (2014), the Act was held not to apply to minority schools, aided or unaided. IV. Article 21A was inserted by the 93rd Amendment.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. Article 21A was inserted by the 86th Amendment (2002). The 93rd Amendment (2005) inserted Article 15(5) on reservation in educational institutions.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-106", "question": "How many of these statements about Indian Young Lawyers Association v. State of Kerala (2018), the Sabarimala case, are correct? I. By a 4:1 majority it struck down the exclusion of women aged 10 to 50 from the temple. II. The lone dissent came from Justice Indu Malhotra. III. The majority held that Ayyappa devotees form a separate religious denomination under Article 26. IV. All four majority judges based their decision on Article 17 (untouchability).", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only I and II are correct. The majority held that Ayyappa devotees are NOT a separate denomination; Justice Malhotra, dissenting, held that they are. Only Justice Chandrachud treated the exclusion as a form of untouchability under Article 17.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id":"polity-fundamental-rights-107","question":"Article 19(5) allows reasonable restrictions on the freedom to move freely and to reside and settle in any part of India in the interests of the general public. What other ground does it name?","options":["Maintaining friendly relations with foreign States","Maintenance of supplies essential to the community","Decency, morality and incitement to an offence","Protecting the interests of any Scheduled Tribe"],"answer":3,"explanation":"Article 19(5) names two grounds: the interests of the general public and the protection of the interests of any Scheduled Tribe. The second one supports Inner Line Permits and limits on outsiders settling in tribal areas. Friendly relations and decency are grounds under Article 19(2) for speech.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-108", "question": "How many of these statements about Public Interest Litigation are correct? I. In S. P. Gupta v. Union of India (1981), the Supreme Court relaxed the rule of locus standi. II. Letters and postcards sent to judges have been treated as writ petitions (epistolary jurisdiction). III. A PIL can be filed in a High Court under Article 226 as well as in the Supreme Court under Article 32. IV. Article 32(2) expressly mentions public interest litigation.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. PIL is a creation of the judges. The Constitution nowhere uses the phrase, and Article 32(2) only lists the writs (habeas corpus, mandamus, prohibition, quo warranto and certiorari) and directions or orders.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-109", "question": "How many of these statements about preventive detention are correct? I. Only Parliament can make a law on preventive detention for reasons of defence, foreign affairs or the security of India. II. Parliament and the State legislatures can both legislate on preventive detention for the security of a State, public order or essential supplies and services. III. Article 22(7) empowers Parliament to prescribe the maximum period of detention. IV. The grounds of detention must be communicated, though facts against the public interest may be withheld.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. I is Entry 9 of the Union List and II is Entry 3 of the Concurrent List. III is Article 22(7)(b), and IV comes from Articles 22(5) and 22(6).", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-110", "question": "Assertion (A): A minority educational institution that receives aid from the State cannot refuse admission to a student only because the student belongs to another religion. Reason (R): Article 29(2) forbids denying admission to a State-maintained or State-aided institution on grounds only of religion, race, caste or language.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Article 29(2) binds aided minority institutions too, so R explains A. The Court has still let such institutions give reasonable preference to their own community (St. Stephen's College, 1992), without shutting out others.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-111", "question": "Which pair of a \"saving\" Article and the Amendment that inserted it is NOT correctly matched?", "options": ["Article 31D – 4th Amendment, 1955", "Article 31A – 1st Amendment, 1951", "Article 31B – 1st Amendment, 1951", "Article 31C – 25th Amendment, 1971"], "answer": 0, "explanation": "Article 31D, which saved laws against \"anti-national activities\", was inserted by the 42nd Amendment (1976) and repealed by the 43rd (1977). The 4th Amendment (1955) only amended Article 31A and added laws to the Ninth Schedule.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "polity-fundamental-rights-112", "question": "Which Article of the Constitution abolishes titles?", "options": ["Article 16", "Article 17", "Article 18", "Article 19"], "answer": 2, "explanation": "Article 18 abolishes titles other than military or academic distinctions. Article 17 abolishes untouchability, a common trap.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC"},
  {"id": "polity-fundamental-rights-113", "question": "The Right against Exploitation is contained in:", "options": ["Articles 19–22", "Articles 23–24", "Articles 25–28", "Articles 29–30"], "answer": 1, "explanation": "Article 23 bans traffic in human beings and forced labour; Article 24 bans child labour in factories, mines and hazardous work. Articles 25–28 are freedom of religion.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "polity-fundamental-rights-114", "question": "Which Article says that no person shall be compelled to pay any tax whose proceeds are used to promote a particular religion?", "options": ["Article 25", "Article 26", "Article 28", "Article 27"], "answer": 3, "explanation": "Article 27 bars taxes earmarked for promoting any particular religion. Article 26 covers denominational rights and Article 28 religious instruction in educational institutions.", "difficulty": "easy", "source": "SSC CGL · State PSCs"},
  {"id": "polity-fundamental-rights-115", "question": "Article 18(1) abolishes titles, but makes an exception for:", "options": ["Military or academic distinctions", "Hereditary titles of former rulers", "Titles conferred by foreign States", "Titles conferred by Parliament by law"], "answer": 0, "explanation": "Article 18(1) bars the State from conferring titles except military or academic distinctions. Foreign titles cannot be accepted by citizens at all (Article 18(2)).", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "polity-fundamental-rights-116", "question": "The law that gives effect to Article 23 by abolishing bonded labour was enacted in:", "options": ["1956", "1986", "1976", "1996"], "answer": 2, "explanation": "The Bonded Labour System (Abolition) Act was passed in 1976. The Child Labour (Prohibition and Regulation) Act, linked to Article 24, came in 1986.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id": "polity-fundamental-rights-117", "question": "In Joseph Shine v. Union of India (2018), the Supreme Court struck down:", "options": ["Section 377 IPC as applied to consenting adults", "Section 124A IPC on sedition", "Section 66A of the IT Act", "Section 497 IPC on adultery"], "answer": 3, "explanation": "Joseph Shine held the adultery provision violative of Articles 14, 15 and 21 because it treated the wife as the husband's property. Section 377 was read down in Navtej Johar (2018) and Section 66A struck down in Shreya Singhal (2015).", "difficulty": "moderate", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-fundamental-rights-118", "question": "Which Article gives every religious denomination the right to manage its own affairs in matters of religion?", "options": ["Article 26", "Article 25", "Article 28", "Article 30"], "answer": 0, "explanation": "Article 26 lets denominations set up religious and charitable institutions, manage their religious affairs, and own and administer property. Article 25 is the individual's freedom of conscience; Article 30 concerns minority educational institutions.", "difficulty": "moderate", "source": "SSC CGL · State PSCs"},
  {"id":"polity-fundamental-rights-119","question":"D. K. Basu v. State of West Bengal (1997) is best known for laying down:","options":["Guidelines on sexual harassment at the workplace","Guidelines on passive euthanasia and living wills","Guidelines on excluding the creamy layer among OBCs","Guidelines for the police on arrest and detention"],"answer":3,"explanation":"D. K. Basu framed requirements such as an arrest memo, informing a relative and medical examination, to prevent custodial violence under Article 21. Workplace guidelines came from Vishaka (1997).","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id": "polity-fundamental-rights-120", "question": "Which ground of discrimination is prohibited by Article 16(2) but NOT listed in Article 15(1)?", "options": ["Sex", "Descent", "Caste", "Place of birth"], "answer": 1, "explanation": "Article 15(1) lists religion, race, caste, sex and place of birth. Article 16(2), on public employment, adds descent and residence.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id":"polity-fundamental-rights-121","question":"In Balaji Raghavan v. Union of India, the Supreme Court held that national awards such as the Bharat Ratna and Padma awards:","options":["Are not titles under Article 18, but must not be used as prefixes or suffixes","Are titles of nobility barred by Article 18, and must therefore be abolished","Are not titles, and so may freely be used as prefixes to the recipient's name","Can be conferred only after Parliament passes a resolution approving each one"],"answer":0,"explanation":"The Court upheld the awards as recognition of merit, not titles of nobility, but said that using them as prefixes or suffixes could lead to forfeiture.","difficulty":"hard","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-fundamental-rights-122","question":"Which case held that the right to “propagate” religion under Article 25 does not include a right to convert another person?","options":["Sri Lakshmindra Thirtha Swamiar (Shirur Mutt), 1954","Rev. Stanislaus v. State of M.P. (1977)","Ismail Faruqui v. Union of India (1994)","Aruna Roy v. Union of India (2002)"],"answer":1,"explanation":"Stanislaus upheld the Madhya Pradesh and Orissa anti-conversion laws, holding that propagation means spreading one's beliefs, not converting others. Shirur Mutt laid down the essential practices test.","difficulty":"hard","source":"UPSC Prelims"},
  {"id": "polity-fundamental-rights-123", "question": "Article 16(4B), which lets unfilled reserved vacancies be carried forward as a separate class outside the 50% ceiling, was inserted by the:", "options": ["77th Amendment, 1995", "81st Amendment, 2000", "85th Amendment, 2001", "93rd Amendment, 2005"], "answer": 1, "explanation": "The 81st Amendment (2000) added Article 16(4B) for backlog vacancies. The 77th added Article 16(4A) and the 85th added consequential seniority to it.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-fundamental-rights-124", "question": "In Janhit Abhiyan v. Union of India (2022), the Supreme Court:", "options": ["Struck down the EWS quota for breaching the 50% ceiling", "Upheld the EWS quota unanimously", "Upheld the 103rd Amendment by a 3:2 majority", "Referred the question to a nine-judge bench"], "answer": 2, "explanation": "A five-judge bench upheld the 10% EWS reservation by 3:2; Chief Justice U. U. Lalit and Justice S. Ravindra Bhat dissented over the exclusion of SC, ST and OBC poor.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id":"polity-fundamental-rights-125","question":"The right to enjoy pollution-free water and air was held to be part of the right to life under Article 21 in:","options":["Olga Tellis v. Bombay Municipal Corporation (1985)","Francis Coralie Mullin v. UT of Delhi (1981)","Parmanand Katara v. Union of India (1989)","Subhash Kumar v. State of Bihar (1991)"],"answer":3,"explanation":"Subhash Kumar (1991) read a clean environment into Article 21. Olga Tellis is about livelihood, Francis Coralie Mullin about human dignity and Parmanand Katara about emergency medical aid.","difficulty":"hard","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-fundamental-rights-126","question":"In State of Punjab v. Davinder Singh (2024), a seven-judge bench of the Supreme Court held that:","options":["The creamy-layer rule can never be applied to Scheduled Castes or Tribes","States may sub-classify Scheduled Castes, overruling E. V. Chinnaiah (2005)","Reservation in promotions for SCs and STs is unconstitutional under Article 16","The 50% ceiling on reservation is absolute and admits no exception"],"answer":1,"explanation":"By 6:1 the Court held SCs are not a homogeneous class and can be sub-classified, overruling the five-judge ruling in E. V. Chinnaiah. Justice Bela Trivedi dissented.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-127","question":"In M. C. Mehta v. State of Tamil Nadu (1996), about child workers in the Sivakasi match and fireworks industry, the Supreme Court directed:","options":["Errant employers to pay compensation per child into a welfare fund","The closure of all match and fireworks factories in Tamil Nadu","Lowering the age limit in Article 24 from 14 years to 12 years","Transfer of all child workers to residential schools run by the Centre"],"answer":0,"explanation":"The Court ordered employers violating the child labour law to pay compensation per child into a welfare fund, and the State to provide education and alternative employment for an adult family member. Article 24 itself sets the age at 14.","difficulty":"hard","source":"UPSC Prelims"},
  {"id": "polity-fundamental-rights-128", "question": "Article 30(1A), which requires that compensation for compulsory acquisition of a minority educational institution's property must not restrict or abrogate its Article 30 right, was inserted by the:", "options": ["42nd Amendment, 1976", "25th Amendment, 1971", "44th Amendment, 1978", "93rd Amendment, 2005"], "answer": 2, "explanation": "When the 44th Amendment removed the Fundamental Right to property, it added Article 30(1A) so minority institutions kept protection against inadequate compensation.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id":"polity-fundamental-rights-129","question":"The “essential religious practices” test for deciding what Article 25 protects was first laid down in:","options":["Ismail Faruqui v. Union of India (1994)","Shayara Bano v. Union of India (2017)","Bijoe Emmanuel v. State of Kerala (1986)","The Shirur Mutt case (1954)"],"answer":3,"explanation":"The Shirur Mutt case (1954) held that religion covers practices essential to it, which the State cannot regulate except as allowed. Ismail Faruqui later applied the idea to hold a mosque not essential to Islam.","difficulty":"hard","source":"UPSC Prelims"},
  {"id": "polity-fundamental-rights-130", "question": "Assertion (A): Article 14 forbids class legislation but permits reasonable classification. Reason (R): A classification is valid if it rests on an intelligible differentia that has a rational nexus with the object of the law.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A: the twin test of intelligible differentia and rational nexus (Anwar Ali Sarkar, 1952; Budhan Choudhry, 1955) separates permissible classification from forbidden class legislation.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-fundamental-rights-131", "question": "Match the case with the right it read into Article 21: A. Francis Coralie Mullin (1981) B. Parmanand Katara (1989) C. Subramanian Swamy v. Union of India (2016) D. Shafin Jahan v. Asokan K. M. (2018) — 1. Emergency medical aid 2. Right to live with human dignity 3. Choice of a life partner 4. Reputation", "options": ["A-1, B-2, C-4, D-3", "A-2, B-1, C-4, D-3", "A-2, B-1, C-3, D-4", "A-4, B-1, C-2, D-3"], "answer": 1, "explanation": "Francis Coralie Mullin: life means life with dignity. Parmanand Katara: doctors must give emergency aid. Subramanian Swamy upheld criminal defamation since reputation is part of Article 21. Shafin Jahan (Hadiya case): choice of spouse.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-fundamental-rights-132", "question": "Consider the following statements: 1. Article 25 is subject to public order, morality, health and the other provisions of Part III. 2. Article 26 is expressly subject to public order, morality, health and also to the other provisions of Part III. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 0, "explanation": "Only 1 is correct. Article 26 is subject only to public order, morality and health; the words “and to the other provisions of this Part” appear in Article 25(1) but not in Article 26.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-fundamental-rights-133", "question": "Consider the following statements about Article 19(2): 1. “Sovereignty and integrity of India” was added as a ground of restriction by the 1st Amendment, 1951. 2. “Public order” and “incitement to an offence” were added by the 1st Amendment, 1951. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 1, "explanation": "Only 2 is correct. The 1st Amendment added public order, friendly relations with foreign States and incitement to an offence. Sovereignty and integrity came with the 16th Amendment, 1963.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-fundamental-rights-134", "question": "The 1976 judgment that held that no one could move a court for habeas corpus while the right under Article 21 stood suspended during the Emergency, with Justice H. R. Khanna dissenting, is:", "options": ["A. K. Gopalan v. State of Madras", "Kharak Singh v. State of U.P.", "ADM Jabalpur v. Shivkant Shukla", "Golaknath v. State of Punjab"], "answer": 2, "explanation": "ADM Jabalpur (4:1) was expressly overruled by the nine-judge bench in K. S. Puttaswamy (2017). The 44th Amendment had already barred suspension of Articles 20 and 21 during an emergency.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-fundamental-rights-135", "question": "Assertion (A): The 93rd Amendment inserted Article 15(5), enabling reservation in private unaided educational institutions other than minority institutions. Reason (R): In P. A. Inamdar (2005), the Supreme Court had held that the State could not impose reservation on unaided private institutions.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A: Parliament passed the 93rd Amendment in response to Inamdar. Article 15(5) was later upheld in Pramati Educational Trust (2014).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-fundamental-rights-136", "question": "Consider the following statements about the child labour law as amended in 2016: 1. Children below 14 may not be employed in any occupation, except helping their family or family enterprise in non-hazardous work outside school hours. 2. Adolescents aged 14 to 18 may not be employed in hazardous occupations and processes. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. The 2016 amendment renamed the 1986 law the Child and Adolescent Labour (Prohibition and Regulation) Act, going beyond Article 24's ban on hazardous work for those under 14.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-fundamental-rights-137", "question": "How many of these statements about the 86th Amendment are correct? I. It inserted Article 21A. II. It substituted Article 45 to provide for early childhood care and education for children below six. III. It added Fundamental Duty 51A(k) on parents and guardians. IV. It was enacted in 2002.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. The 86th Amendment (2002) made education for 6–14-year-olds a Fundamental Right, shifted Article 45 to children under six, and added the parental duty in Article 51A(k).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-fundamental-rights-138", "question": "Arrange these freedom of speech judgments in chronological order: 1. Kedar Nath Singh (sedition upheld but read down) 2. Shreya Singhal (Section 66A struck down) 3. Romesh Thappar (ban on a journal struck down) 4. S. G. Vombatkere (sedition prosecutions put in abeyance)", "options": ["1, 3, 2, 4", "3, 1, 4, 2", "1, 3, 4, 2", "3, 1, 2, 4"], "answer": 3, "explanation": "Romesh Thappar (1950), Kedar Nath Singh (1962), Shreya Singhal (2015) and S. G. Vombatkere (2022).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-fundamental-rights-139", "question": "Match the case with the protection it recognised: A. Sunil Batra (1978) B. Prem Shankar Shukla (1980) C. Chameli Singh (1996) D. Satwant Singh Sawhney (1967) — 1. Right to shelter 2. Right to travel abroad 3. Protection against routine handcuffing 4. Protection of prisoners against solitary confinement and bar fetters", "options": ["A-3, B-4, C-1, D-2", "A-4, B-3, C-1, D-2", "A-4, B-3, C-2, D-1", "A-4, B-1, C-3, D-2"], "answer": 1, "explanation": "Sunil Batra protected prisoners from solitary confinement and bar fetters, Prem Shankar Shukla restricted handcuffing, Chameli Singh recognised shelter, and Satwant Singh Sawhney treated travel abroad as part of personal liberty.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-fundamental-rights-140", "question": "Consider the following statements: 1. In M. Nagaraj (2006), the Supreme Court upheld Article 16(4A) but required the State to show backwardness, inadequate representation and overall administrative efficiency before reserving promotions. 2. In Jarnail Singh (2018), it held that the State need not collect quantifiable data on the backwardness of SCs and STs for such promotions. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. Jarnail Singh modified Nagaraj only on proving backwardness of SCs and STs, while keeping the other conditions and applying the creamy-layer principle.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id":"polity-fundamental-rights-141","question":"How many of these statements about K. S. Puttaswamy v. Union of India (2017) are correct? I. It was decided by nine judges. II. The decision was by a 5:4 majority. III. It overruled M. P. Sharma and Kharak Singh to the extent they denied a right to privacy. IV. The same nine-judge bench also decided the validity of the Aadhaar Act.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are correct. II is wrong: the nine-judge bench was unanimous. IV is wrong: the Aadhaar Act was decided separately in 2018 by a five-judge bench.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-142","question":"Under Article 13, only the part of a statute that violates a Fundamental Right is struck down, if it can be separated from the rest without defeating the law’s purpose. This doctrine of severability was explained in:","options":["Bhikaji Narain Dhakras v. State of Madhya Pradesh (1955)","Basheshar Nath v. Commissioner of Income Tax (1959)","R. M. D. Chamarbaugwala v. Union of India (1957)","Kesavananda Bharati v. State of Kerala (1973)"],"answer":2,"explanation":"R. M. D. C. (1957), on prize competitions, set out when the valid part of a law survives. Bhikaji Narain is the doctrine of eclipse and Basheshar Nath the bar on waiving Fundamental Rights.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-143","question":"Consider the following statements about Jarnail Singh v. Lachhmi Narain Gupta (2018): 1. It held that M. Nagaraj (2006) need not be referred to a larger bench. 2. It held that the State need not collect quantifiable data on the backwardness of Scheduled Castes and Scheduled Tribes before giving them reservation in promotion. 3. It held that the creamy layer principle can be applied to Scheduled Castes and Scheduled Tribes in promotions. Which of the statements given above is/are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":3,"explanation":"All three are correct: the five-judge bench declined to revisit Nagaraj, dropped only its requirement of data on SC/ST backwardness (kept the data on inadequate representation and efficiency), and applied the creamy layer test.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-144","question":"In which case did the Supreme Court strike down an order fixing the price of newspapers according to their number of pages, holding that a restriction on circulation infringes the freedom of the press?","options":["Romesh Thappar v. State of Madras (1950)","Brij Bhushan v. State of Delhi (1950)","Indian Express Newspapers v. Union of India (1985)","Sakal Papers v. Union of India (1962)"],"answer":3,"explanation":"Sakal Papers (1962) held that the price-and-page schedule curtailed circulation, which is part of Article 19(1)(a), and could not be justified as a restriction on business under Article 19(6). Romesh Thappar and Brij Bhushan were 1950 cases on a ban and on pre-censorship.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-145","question":"The right to know, as a part of the freedom of speech and expression, was first recognised by the Supreme Court in a case concerning the disclosure of the ‘Blue Book’ on the Prime Minister’s security. Which case?","options":["Indira Nehru Gandhi v. Raj Narain (1975)","S. P. Gupta v. Union of India (1981)","State of U.P. v. Raj Narain (1975)","Union of India v. Association for Democratic Reforms (2002)"],"answer":2,"explanation":"State of U.P. v. Raj Narain (1975) arose from the Allahabad election petition but was a separate case on privilege over the Blue Book. Indira Nehru Gandhi v. Raj Narain is the 39th Amendment case; ADR later gave voters a right to know about candidates.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-146","question":"In which case did the Supreme Court hold that commercial speech, such as advertising, is protected by Article 19(1)(a), departing from an earlier view that advertisements are mere trade?","options":["Hamdard Dawakhana v. Union of India (1960)","Bennett Coleman and Co. v. Union of India (1972)","Secretary, Ministry of I&B v. Cricket Association of Bengal (1995)","Tata Press Ltd. v. Mahanagar Telephone Nigam Ltd. (1995)"],"answer":3,"explanation":"Tata Press (1995), on advertisements in a telephone directory, recognised commercial speech. Hamdard Dawakhana (1960), the trap, had treated advertisements for objectionable drugs as trade rather than expression.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-147","question":"In which case did the Supreme Court hold that airwaves are public property to be used for the public good, and that the right to telecast a sporting event is part of the freedom of expression?","options":["Life Insurance Corporation v. Manubhai D. Shah (1992)","Tata Press Ltd. v. Mahanagar Telephone Nigam Ltd. (1995)","Ministry of I&B v. Cricket Association of Bengal (1995)","Shreya Singhal v. Union of India (2015)"],"answer":2,"explanation":"The Cricket Association of Bengal case (1995) dealt with telecasting cricket matches and called for an independent public authority to regulate airwaves. Manubhai Shah concerned a right of reply and the screening of a documentary on Doordarshan.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-148","question":"Consider the following statements: 1. The right to form associations under Article 19(1)(c) includes a guaranteed right to go on strike. 2. In T. K. Rangarajan v. Government of Tamil Nadu (2003), the Supreme Court said government employees have no fundamental, legal or moral right to strike. 3. The right to form a union does not include a fundamental right to have it recognised or to bargain collectively. Which of the statements given above is/are correct?","options":["1 and 2 only","2 and 3 only","3 only","1, 2 and 3"],"answer":1,"explanation":"Forming a union is protected, but its activities, such as strikes, recognition and collective bargaining, are regulated by ordinary law and are not Fundamental Rights; Rangarajan applied this to government servants.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-149","question":"Consider the following statements about Article 20(3): 1. The protection is available to an accused even during police interrogation, before any trial begins. 2. Compelling an accused to give fingerprints or a specimen of handwriting does not violate it. 3. The protection is available to every witness in any proceeding, whether or not the witness is accused of an offence. Which of the statements given above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Nandini Satpathy (1978) extended the bar to police questioning and Kathi Kalu Oghad (1961) held that identification material is not ‘testimony’. Article 20(3) protects only a person ‘accused of any offence’.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-150","question":"Which case held that the right to life under Article 21 does not include a right to die, upheld the penal provision on attempted suicide, and overruled an earlier judgment to the contrary?","options":["Gian Kaur v. State of Punjab (1996)","P. Rathinam v. Union of India (1994)","Aruna Ramchandra Shanbaug v. Union of India (2011)","Common Cause v. Union of India (2018)"],"answer":0,"explanation":"The five-judge bench in Gian Kaur overruled P. Rathinam, which had struck down the attempted-suicide offence. Aruna Shanbaug and Common Cause later dealt with passive euthanasia and living wills.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-151","question":"Consider the following statements about the Right to Education: 1. In Society for Unaided Private Schools of Rajasthan (2012), the Supreme Court upheld the 25% reservation of entry-level seats in unaided non-minority schools for disadvantaged children. 2. In Pramati Educational and Cultural Trust (2014), it held that the RTE Act does not apply to minority schools, aided or unaided. 3. Pramati struck down Article 21A as violating the basic structure. Which of the statements given above is/are correct?","options":["1 and 2 only","2 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Pramati upheld both Article 21A and Article 15(5) but exempted all minority schools from the RTE Act to protect Article 30. The 2012 case upheld Section 12(1)(c) for unaided non-minority schools.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-152","question":"Under Article 22(3), the safeguards in Article 22(1) and (2), such as being told the grounds of arrest, consulting a lawyer and production before a magistrate within 24 hours, do NOT apply to:","options":["Any foreigner, and any person arrested for a non-bailable offence","A person arrested under a special criminal law such as an anti-terror law","A member of the armed forces arrested for an ordinary civil offence","An enemy alien, and a person held under a preventive detention law"],"answer":3,"explanation":"Article 22(3) excludes only enemy aliens and preventive detainees, whose separate safeguards are in Article 22(4) to (7). Ordinary foreigners and people arrested under special punitive laws keep these protections.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-153","question":"Article 23(2) allows the State to impose compulsory service for public purposes but bars discrimination in doing so on certain grounds. Which of these is NOT one of those grounds?","options":["Religion","Caste","Class","Sex"],"answer":3,"explanation":"Article 23(2) lists only religion, race, caste or class. Sex is absent, so a compulsory service scheme confined to men would not breach this clause.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-154","question":"Article 29(2) bars the denial of admission to an educational institution maintained by the State or receiving State aid on grounds only of certain factors. Which set is correct?","options":["Religion, race, caste, sex, place of birth","Religion, race, caste, sex, descent","Religion, race, caste, language","Religion, caste, language, residence"],"answer":2,"explanation":"Article 29(2) names religion, race, caste and language. Sex and place of birth belong to Article 15(1), and descent and residence to Article 16(2), which are the traps.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-155","question":"In I. R. Coelho v. State of Tamil Nadu (2007), the Supreme Court held that laws placed in the Ninth Schedule:","options":["inserted after 24 April 1973 can be tested against the basic structure","are wholly immune from judicial review, whatever the date of their insertion","placed there before 1973 can be struck down for violating any Fundamental Right","can be challenged only in the Supreme Court under Article 32, not in High Courts"],"answer":0,"explanation":"The nine-judge bench took 24 April 1973, the date of Kesavananda Bharati, as the cut-off: later insertions get no blanket immunity and are tested against the basic structure, including the essence of Articles 14, 19 and 21. Earlier insertions stay protected, as upheld in Waman Rao.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-156","question":"In which case did the Bombay High Court hold that uncodified personal laws are not ‘laws in force’ within Article 13 and so cannot be tested against Fundamental Rights?","options":["Mohd. Ahmed Khan v. Shah Bano Begum","Sarla Mudgal v. Union of India","Shayara Bano v. Union of India","State of Bombay v. Narasu Appa Mali"],"answer":3,"explanation":"Narasu Appa Mali (1952) upheld a Bombay law against bigamy and held that personal law as such is outside Article 13; it was much debated in the triple talaq and Sabarimala cases.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-157","question":"How many of these statements about Article 18 are correct? I. The State cannot confer any title except a military or academic distinction. II. A citizen of India cannot accept any title from a foreign State. III. A person holding an office of profit or trust under the State needs the President’s consent to accept any present, emolument or office from a foreign State. IV. Article 18 itself lays down a penalty for its breach.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III restate Article 18(1), (2) and (4). Article 18 prescribes no penalty; enforcement is left to law made by Parliament.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-158","question":"Which provision ensures that a law creating a State monopoly in a trade or business, such as nationalised road transport, cannot be challenged under Article 19(1)(g) merely because it excludes citizens from that trade?","options":["Article 301","Article 31C","Article 19(6)","Article 304(b)"],"answer":2,"explanation":"Article 19(6)(ii), added by the 1st Amendment (1951), protects trade carried on by the State or its corporations ‘to the exclusion, complete or partial, of citizens’. Article 301 is the freedom of inter-State trade and Article 304(b) lets States restrict it, so neither shields a monopoly from Article 19(1)(g).","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-159","question":"In K. A. Abbas v. Union of India (1970), the Supreme Court held that:","options":["pre-censorship of films is void, since every prior restraint on expression is unconstitutional","pre-censorship of films is valid, since films stir people more than other media","films are mere entertainment and so fall outside the scope of Article 19(1)(a)","only Parliament, and not an appointed board, may decide which films can be shown"],"answer":1,"explanation":"The Court upheld film censorship, noting the strong effect of moving pictures, while insisting the standards be reasonable and clearly stated.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-160","question":"In S. Rangarajan v. P. Jagjivan Ram (1989), about a Tamil film on reservations, the Supreme Court held that:","options":["threats of protest cannot justify suppression; the danger must be like a ‘spark in a powder keg’","the State may revoke a film’s certificate whenever any group threatens violence over it","films criticising the reservation policy may be banned because they disturb public order","certification decisions of the Censor Board are final and cannot be reviewed by any court of law"],"answer":0,"explanation":"The Court restored the film’s certificate, holding that the State must protect expression rather than give in to threats, and that restriction needs a proximate and direct link to public disorder.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-161","question":"A tribunal begins hearing a dispute that is clearly outside its jurisdiction, and the hearing is still going on. An aggrieved party wants a higher court to stop it from proceeding further. The appropriate writ is:","options":["Certiorari","Prohibition","Mandamus","Quo warranto"],"answer":1,"explanation":"Prohibition is preventive and issues while the proceedings are pending; certiorari is curative and quashes a decision already made. Both lie against judicial and quasi-judicial bodies.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"polity-fundamental-rights-162","question":"A private restaurant open to the public refuses entry to a customer because of his caste. Which provision directly forbids this, even though the restaurant is not ‘the State’?","options":["Article 14","Article 15(2)","Article 16(2)","Article 29(2)"],"answer":1,"explanation":"Article 15(2) bars restrictions on access to shops, public restaurants, hotels and places of public entertainment, and so binds private persons. Article 14 binds only the State, 16(2) concerns public jobs and 29(2) admission to aided institutions.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL"},
  {"id":"polity-fundamental-rights-163","question":"Under Article 26, which right of a religious denomination is expressly to be exercised ‘in accordance with law’?","options":["To establish and maintain institutions for religious and charitable purposes","To manage its own affairs in matters of religion","To own and acquire movable and immovable property","To administer its property"],"answer":3,"explanation":"Clause (d) lets a denomination administer its property ‘in accordance with law’, so the State may regulate administration but cannot take it away altogether, as held in Ratilal Panachand Gandhi (1954).","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-164","question":"In which case did the Supreme Court first hold that Article 16(4) is not an exception to Article 16(1) but a facet of equality of opportunity itself?","options":["State of Kerala v. N. M. Thomas (1976)","M. R. Balaji v. State of Mysore (1962)","Indra Sawhney v. Union of India (1992)","State of Madras v. Champakam Dorairajan (1951)"],"answer":0,"explanation":"N. M. Thomas (1976) treated Article 16(4) as a facet of the equality of opportunity in Article 16(1), a view Indra Sawhney (1992) later endorsed. Earlier cases such as T. Devadasan (1964), following M. R. Balaji (1962, an Article 15(4) case that suggested keeping reservations below 50%), had treated such provisions as exceptions.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-165","question":"Consider the following statements: 1. M. R. Balaji (1962) first said that reservations should generally stay below 50%. 2. Indra Sawhney (1992) held that Article 16(4) does not permit reservation in promotions. 3. Indra Sawhney upheld the 10% reservation for economically poorer sections not covered by other reservation schemes. Which of the statements given above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Indra Sawhney struck down the 1991 order reserving 10% on an economic criterion alone, and ruled out reservation in promotions, which led to Article 16(4A) in 1995. Economic reservation came only with the 103rd Amendment (2019).","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-166","question":"A law passed in 2020 increases the punishment for an offence. A person who committed that offence in 2018 is tried in 2021. Under Article 20(1), he can be given:","options":["only the penalty in force when the offence was committed","the higher penalty, since the trial took place after the new law","either penalty, at the court’s discretion","no penalty, since the law has changed since the offence"],"answer":0,"explanation":"Article 20(1) bars a penalty greater than the one in force when the act was committed. What matters is the date of the offence, not the date of trial.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL"},
  {"id":"polity-fundamental-rights-167","question":"Article 32(2) empowers the Supreme Court to issue directions, orders or writs, ‘including writs in the nature of’ five named writs. Which of these is NOT one of them?","options":["Quo warranto","Certiorari","Injunction","Prohibition"],"answer":2,"explanation":"The five named writs are habeas corpus, mandamus, prohibition, quo warranto and certiorari. An injunction is a civil remedy, though the Court may issue other directions too.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL"},
  {"id":"polity-fundamental-rights-168","question":"Article 15(2) bars denying a citizen access to certain places on grounds only of religion, race, caste, sex or place of birth. To which of these does Article 15(2) apply?","options":["A well dug and maintained by a private trust solely for the use of its own members","A bathing ghat built by a private person but dedicated to the use of the general public","A swimming pool in a private residential club that admits only its own enrolled members","A playground of a private unaided school that is open only to its own enrolled pupils"],"answer":1,"explanation":"Article 15(2)(b) covers wells, tanks, bathing ghats, roads and places of public resort maintained wholly or partly out of State funds OR dedicated to the use of the general public, so public dedication is enough even without State money. The other places are not open to the public at all.","difficulty":"very-hard","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-fundamental-rights-169","question":"In Pradeep Kumar Biswas v. Indian Institute of Chemical Biology (2002), a seven-judge bench ruled on the status of the Council of Scientific and Industrial Research (CSIR). It held that CSIR:","options":["Is not ‘State’, because it is only a society registered under the Societies Registration Act","Is ‘State’ only for claims under Articles 14 and 16, and not for any of the other Fundamental Rights","Is ‘State’ under Article 12, and it overruled Sabhajit Tewary (1975), which had held otherwise","Is ‘State’ only because it was created directly by an Act of Parliament as a statutory body"],"answer":2,"explanation":"Applying the test of deep and pervasive financial, functional and administrative control by the government, the Court held CSIR to be an ‘other authority’ under Article 12 and overruled Sabhajit Tewary. Registration as a society does not settle the question, and CSIR is not a statutory body.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-170","question":"In Mithu v. State of Punjab (1983), the Supreme Court struck down Section 303 of the Indian Penal Code. What did that section provide?","options":["Death by hanging as the only lawful method of carrying out every death sentence","Life imprisonment without any remission for a person convicted of murder twice","A death sentence for murder at the trial judge's discretion without recorded reasons","A mandatory death sentence for murder committed by a person already serving life"],"answer":3,"explanation":"Section 303 left the court no choice: a life convict who committed murder had to be sentenced to death. The Court held a mandatory death sentence unfair, unjust and unreasonable under Articles 14 and 21. Hanging as a method was upheld separately in Deena Dayal (1983).","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-fundamental-rights-171","question":"How many of these statements about the right to property today are correct? I. It is a constitutional right under Article 300A in Part XII. II. A person deprived of property can move the Supreme Court directly under Article 32 to enforce it. III. Deprivation must be by authority of law, so an executive order without legal backing is not enough. IV. The 42nd Amendment, 1976 removed both Article 19(1)(f) and Article 31 from Part III.","options":["Only three","Only two","Only one","All four"],"answer":1,"explanation":"I and III are correct: property is a constitutional right under Article 300A, and any deprivation needs authority of law. II is wrong: it cannot be enforced under Article 32. IV is wrong: Articles 19(1)(f) and 31 were removed by the 44th Amendment (1978), not the 42nd.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-172","question":"Consider these statements about Article 14: 1. ‘Equality before law’ is a negative concept of British origin, while ‘equal protection of the laws’ is a positive concept drawn from the US Constitution. 2. Article 14 protects any person, including a company or a foreign national. 3. The immunity of the President and Governors from criminal proceedings during their term under Article 361 is an exception to equality before law. Which of these are correct?","options":["1 and 2 only","1, 2 and 3","2 and 3 only","1 and 3 only"],"answer":1,"explanation":"Article 14 combines the British idea of no special privilege before the law with the American idea of equal treatment in equal circumstances, and its word ‘person’ covers companies and foreigners. Article 361 immunity for the President and Governors is a recognised exception to equality before law, so all three are correct.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-173","question":"In Anuj Garg v. Hotel Association of India (2007), the Supreme Court struck down a provision of the Punjab Excise Act, 1914, as applied in Delhi, that barred:","options":["Women from holding a licence to run a liquor vend anywhere in the National Capital Territory","Persons below 25 from buying liquor at any licensed shop in the National Capital Territory","Men below 25 and all women from being employed where liquor is consumed by the public","Women from serving as excise inspectors in districts that had declared total prohibition"],"answer":2,"explanation":"Section 30 barred employing any man under 25 or any woman in premises where liquor is consumed by the public. The Court held that ‘protective’ laws resting on stereotypes about women must pass strict scrutiny and proportionality, and struck the bar down under Articles 14, 15 and 19(1)(g).","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-174","question":"In which case did the Supreme Court hold that telephone tapping invades the right to privacy under Article 21, and lay down safeguards for interception orders under the Indian Telegraph Act, 1885?","options":["R. Rajagopal v. State of Tamil Nadu (1994)","Kharak Singh v. State of Uttar Pradesh (1963)","Govind v. State of Madhya Pradesh (1975)","PUCL v. Union of India (1997)"],"answer":3,"explanation":"In PUCL (1997) the Court held a telephone conversation to be part of private life, so interception must follow safeguards such as orders by the Home Secretary and review by a committee. Rajagopal dealt with privacy against press publication; Kharak Singh and Govind dealt with police surveillance.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-fundamental-rights-175","question":"A State law charges religious institutions a fee to meet the cost of a department that supervises the proper administration of their endowments. Judged against Article 27, the levy is:","options":["Valid, as Article 27 bars only a tax that promotes a religion, not a fee for a service","Invalid, because Article 27 forbids every compulsory payment demanded from a religious body","Valid only if the fee is collected at the same rate from the institutions of every religion","Invalid, because only Parliament may levy a charge on religious endowments under Article 26"],"answer":0,"explanation":"In the 1954 religious endowments cases the Supreme Court held that Article 27 bars a tax whose proceeds are appropriated to promote or maintain a religion. A fee that pays for supervising the secular administration of endowments is not such a tax, so it is valid.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-176","question":"In M. Ismail Faruqui v. Union of India (1994), upholding the acquisition of land at Ayodhya, the Supreme Court made which observation on Articles 25 and 26?","options":["A place of worship of any religion is immune from compulsory acquisition by the State","A mosque is not an essential part of the practice of Islam, and namaz can be offered anywhere","Religious property can be acquired only if the religious denomination concerned gives its consent","Places of worship can be acquired only under a law that Article 31A saves from challenge"],"answer":1,"explanation":"The Court held that places of worship, mosques included, can be acquired under the State's sovereign power, since a mosque is not essential to Islamic practice and prayer may be offered even in the open. Only a place of special significance, whose loss would hit the religion itself, could claim protection.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-177","question":"Arrange these preventive detention laws in the order in which they were enacted: 1. National Security Act 2. Maintenance of Internal Security Act 3. Preventive Detention Act 4. Conservation of Foreign Exchange and Prevention of Smuggling Activities Act","options":["3, 2, 1, 4","2, 3, 4, 1","3, 2, 4, 1","3, 4, 2, 1"],"answer":2,"explanation":"Preventive Detention Act 1950, MISA 1971, COFEPOSA 1974 and NSA 1980. All of them rest on Article 22, which permits preventive detention subject to the Advisory Board safeguards.","difficulty":"hard","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-fundamental-rights-178","question":"In Secretary, Ministry of Defence v. Babita Puniya (2020), the Supreme Court:","options":["Upheld limits on command postings for women officers as based on their differing physical standards","Held that Article 33 bars any challenge to Army service rules on the ground of equality","Upheld the exclusion of women from the National Defence Academy as a reasonable classification","Directed that women officers on Short Service Commission be considered for Permanent Commission"],"answer":3,"explanation":"The Court rejected arguments based on physiology and social norms as stereotypes, held that women SSC officers must be considered for Permanent Commission and command posts, and treated this as a matter of equality under Article 14. Article 33 lets Parliament restrict rights by law; it does not bar such claims.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-179","question":"In Supriyo v. Union of India (2023), the Constitution Bench hearing petitions on marriage equality for queer couples:","options":["Held unanimously that there is no Fundamental Right to marry, leaving recognition to Parliament","Held by a 3:2 majority that queer couples have a Fundamental Right to marry under Article 21","Read the Special Marriage Act, 1954 by a 3:2 majority so as to include couples of the same sex as well","Struck down the Special Marriage Act, 1954 to the extent that it excluded same-sex couples"],"answer":0,"explanation":"All five judges declined to strike down or read words into the Special Marriage Act and held that there is no unqualified Fundamental Right to marry. They split 3:2 on recognising civil unions, which the majority also left to the legislature.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-180","question":"In Aishat Shifa v. State of Karnataka (2022), on the ban on wearing the hijab in government pre-university colleges, the two-judge bench:","options":["Unanimously upheld the ban, holding that the hijab is not an essential religious practice","Gave a split verdict, so the matter went to the Chief Justice for a larger bench","Unanimously struck down the ban as violating Articles 19(1)(a) and 25 of the Constitution","Declined to decide the case and tagged it with the pending Sabarimala review reference"],"answer":1,"explanation":"Justice Hemant Gupta upheld the Karnataka High Court ruling that sustained the ban, while Justice Sudhanshu Dhulia set it aside, stressing choice and girls' education. A split verdict of a two-judge bench sends the case to the Chief Justice for a larger bench.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-fundamental-rights-181","question":"How many of these statements about the rights of minorities under Article 30 are correct? I. Linguistic minorities, and not only religious ones, can claim Article 30. II. The right covers institutions set up before the Constitution came into force. III. The State may not impose any regulation, even on academic standards, on an aided minority institution. IV. Article 30 protects only institutions that teach the minority's own religion or language.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are correct: Article 30(1) covers minorities based on religion or language, and the Kerala Education Bill reference (1958) covered pre-1950 institutions. III is wrong: reasonable regulation of standards is allowed. IV is wrong: they may give general secular education.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-182","question":"In Naresh Shridhar Mirajkar v. State of Maharashtra (1966), a High Court judge had ordered that a witness's evidence not be published, and journalists challenged the order under Article 32. The Supreme Court held that:","options":["The order violated Article 19(1)(a), as courts are ‘State’ for every purpose","Only a Constitution Bench could quash a High Court judge's order under Article 32","The order was void, since a High Court has no inherent power to hold a trial in camera","A High Court's judicial order cannot be quashed by a writ under Article 32"],"answer":3,"explanation":"The majority held that a judicial decision of a superior court, even one that affects a Fundamental Right, is not open to a writ under Article 32; the remedy is appeal. It also held that a High Court has inherent power to restrict publicity where justice requires it.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-183","question":"A law made after 1950 violates Article 19(1)(g), a right available only to citizens. Following State of Gujarat v. Ambica Mills (1974), what is the position of this law?","options":["It is void only against citizens and remains operative against non-citizens and companies","It is void ab initio for everyone, since Article 13(2) forbids the State from making it at all","It lies dormant under the doctrine of eclipse and revives if the right is later suspended","It is valid until a court declares it void, after which it is void against every person"],"answer":0,"explanation":"Ambica Mills held that ‘void’ in Article 13(2) is relative: a post-Constitution law that infringes a citizens-only right is void only against those who hold the right, and stays operative against non-citizens such as companies. It is not void against everyone, as Deep Chand (1959) had suggested.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-184","question":"Arrange these rulings on Section 377 of the IPC and privacy in chronological order: 1. Navtej Singh Johar v. Union of India 2. Suresh Kumar Koushal v. Naz Foundation 3. Naz Foundation v. Government of NCT of Delhi (Delhi High Court) 4. K. S. Puttaswamy v. Union of India (privacy)","options":["3, 4, 2, 1","3, 2, 4, 1","2, 3, 4, 1","3, 2, 1, 4"],"answer":1,"explanation":"The Delhi High Court read down Section 377 in Naz (2009); the Supreme Court reversed it in Koushal (2013); Puttaswamy (2017) criticised Koushal while declaring privacy a Fundamental Right; and Navtej (2018) decriminalised consensual relations between adults of the same sex.","difficulty":"hard","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-fundamental-rights-185","question":"In Excel Wear v. Union of India (1978), the Supreme Court struck down Section 25-O of the Industrial Disputes Act, which required prior government permission to close an undertaking. Its main reasoning was that:","options":["Closure of industries is a trade policy matter reserved for Parliament, not for courts","Workers have no Fundamental Right to employment, so the provision served no purpose","Freedom of business includes a right to close it, and the curb was unreasonable","The provision dealt with a State List subject, so Parliament lacked competence to make it"],"answer":2,"explanation":"The Court held that the freedom of business under Article 19(1)(g) includes the right not to carry it on, and that the unguided power to refuse permission was not a reasonable restriction under Article 19(6). The right to close is not absolute, and a revised provision was later upheld.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-186","question":"A person runs a prize competition in which winning depends wholly on chance and claims that a ban on it violates his freedom of trade under Article 19(1)(g). Following R. M. D. Chamarbaugwala v. Union of India (1957), the claim fails because:","options":["Article 19(1)(g) protects only trades carried on under a licence granted by the State","A prize competition is a lottery, which is a Union List subject outside Part III","Gaming is protected, but only Parliament may restrict it under Article 19(6)","Gambling is not ‘trade’ or ‘business’ at all, so it lies outside Article 19(1)(g)"],"answer":3,"explanation":"The Court held that gambling is res extra commercium: it is not trade, business or commerce in the constitutional sense, so Article 19(1)(g) does not reach it. Competitions involving substantial skill were treated differently.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-187","question":"In Air India v. Nergesh Meerza (1981), the Supreme Court examined service rules for air hostesses. Which rule did it strike down as arbitrary and violative of Article 14?","options":["Termination of service on the air hostess's first pregnancy","A retirement age for air hostesses lower than for male pursers","A bar on marriage within four years of joining the service","Separate promotion channels for air hostesses and pursers"],"answer":0,"explanation":"The Court struck down the rule ending service on first pregnancy as unreasonable and an affront to womanhood. It upheld the bar on marriage within the first four years and treated air hostesses and pursers as separate cadres, so different service conditions were not sex discrimination as such.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-188","question":"In Yusuf Abdul Aziz v. State of Bombay (1954), a man charged with adultery argued that Section 497 of the IPC discriminated by sex because the wife could not be punished even as an abettor. The Supreme Court:","options":["Struck down Section 497 as hostile discrimination against men under Article 15(1)","Upheld Section 497 as a special provision for women permitted by Article 15(3)","Upheld Section 497 because Article 14 does not apply to provisions of criminal law","Read Section 497 down so that the wife too could be punished as an abettor"],"answer":1,"explanation":"The Court treated the exemption of the wife as a special provision for women saved by Article 15(3). Joseph Shine (2018) later struck down Section 497 itself, holding that it treated a woman as her husband's property.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-189","question":"In Church of God (Full Gospel) in India v. K. K. R. Majestic Colony Welfare Association (2000), the Supreme Court held that:","options":["Prayer through loudspeakers is an essential practice protected by Article 25","Noise rules apply to temples and mosques but not to churches in residential areas","No religion prescribes prayer that disturbs others' peace through loudspeakers","Curbs on loudspeakers at places of worship can be made only by Parliament"],"answer":2,"explanation":"The Court held that Article 25 does not protect prayer through voice amplifiers or drums that disturb others, since no religion requires it, and that noise control rules apply to all places of worship alike.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-fundamental-rights-190","question":"In Amit Sahni v. Commissioner of Police (2020), arising from the Shaheen Bagh protest in Delhi, the Supreme Court held that:","options":["A peaceful protest may occupy any public road until the government responds to it","The right to protest is only a statutory right that the police may suspend at will","Protests against a law passed by Parliament are not protected by Article 19(1)(b)","Public ways cannot be occupied indefinitely; protests belong at designated sites"],"answer":3,"explanation":"The Court affirmed the right to peaceful protest under Articles 19(1)(a) and (b) but held that it must be balanced against others' freedom of movement, so public roads cannot be occupied indefinitely and the administration may clear such blockades.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-191","question":"How many of these statements about Ashoka Kumar Thakur v. Union of India (2008) are correct? I. It upheld the 93rd Amendment as far as it applied to State-maintained and aided institutions. II. It required the creamy layer to be excluded from OBC reservation in central educational institutions. III. It finally decided that Article 15(5) is valid in its application to private unaided institutions.","options":["Only two","Only one","All three","None"],"answer":0,"explanation":"The Court upheld the 93rd Amendment and the 27% OBC quota in central institutions with the creamy layer excluded (I, II correct). It expressly left open whether Article 15(5) is valid for private unaided institutions, which was settled later in Pramati (2014), so III is wrong.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-192","question":"Arrange these milestones on reservation in promotions in chronological order: 1. M. Nagaraj v. Union of India 2. 77th Amendment inserting Article 16(4A) 3. General Manager, Southern Railway v. Rangachari 4. Indra Sawhney v. Union of India","options":["3, 2, 4, 1","3, 4, 2, 1","4, 3, 2, 1","3, 4, 1, 2"],"answer":1,"explanation":"Rangachari (1961) held that Article 16(4) covers promotions; Indra Sawhney (1992) overruled this and barred reservation in promotions; the 77th Amendment (1995) restored it for SCs and STs through Article 16(4A); and Nagaraj (2006) upheld that clause subject to conditions.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-193","question":"A private school recognised by the State, but not maintained out of State funds, holds religious instruction during school hours. A Class 8 pupil does not want to attend. Under Article 28(3):","options":["The pupil must attend, since Article 28 restricts only wholly State-funded schools","The school must stop all religious instruction, since recognition makes it a State school","The pupil cannot be required to attend without the consent of the pupil's guardian","The pupil may stay away only if the school is run by a minority under Article 30"],"answer":2,"explanation":"Article 28(3) says no one attending an institution recognised by the State or receiving State aid shall be required to take part in its religious instruction or worship without consent, given by the guardian for a minor. Only wholly State-maintained institutions face the outright bar of Article 28(1).","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-194","question":"The second proviso to Article 31A(1), added by the 17th Amendment (1964), protects a person whose land is acquired by the State. What does it require?","options":["Prior approval of each acquisition by a resolution of the State Legislative Assembly","Payment of compensation in cash within one year from the date of acquisition","Placing the law in the Ninth Schedule before any of the land is taken over","Market-value compensation for land within the ceiling under personal cultivation"],"answer":3,"explanation":"Where land under a person's personal cultivation and within the statutory ceiling is acquired, the law must provide compensation not less than its market value. It is one of the few places where the Constitution still speaks of market value.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-195","question":"In Sheela Barse v. State of Maharashtra (1983), acting on a journalist's letter about the treatment of women in police custody, the Supreme Court directed that:","options":["Female suspects be kept in separate lock-ups guarded by female constables","Special courts for women be set up in every district to try their cases","Every arrest of a woman be recorded on video and sent to the High Court","Women prisoners be given bail as of right in all bailable and non-bailable cases"],"answer":0,"explanation":"The Court directed separate, well-guarded lock-ups for women with female constables, interrogation of women only in the presence of policewomen, and prompt intimation of arrests to legal aid bodies so that arrested persons get legal help.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-fundamental-rights-196","question":"In Lata Singh v. State of U.P. (2006), about the harassment of an adult woman who had married outside her caste, the Supreme Court held that:","options":["An adult may marry anyone, and police must act against those who threaten such couples","An inter-caste marriage is valid only if registered under the Special Marriage Act, 1954","Parents may seek annulment of an adult child's inter-caste marriage under Article 226","Caste panchayats may advise on marriages so long as they impose no penalty on the couple"],"answer":0,"explanation":"The Court held that an adult is free to marry a person of choice, that inter-caste marriages are in the national interest, and directed the police to protect such couples and prosecute those who threaten or harass them; it condemned so-called honour killings.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-fundamental-rights-197","question":"In Zahira Habibullah Sheikh v. State of Gujarat (2004), the Best Bakery case, the Supreme Court set aside the acquittals and ordered a retrial. What did it do to secure a fair trial?","options":["It ordered the case to be tried afresh by a special bench of the Gujarat High Court","It transferred the retrial to a court in Maharashtra, outside the State of Gujarat","It gave the retrial to a court-martial because witnesses feared the State police","It ordered the retrial to be held before a sessions judge from another district of Gujarat"],"answer":1,"explanation":"Holding that a fair trial is part of Article 21 and that witnesses had been intimidated, the Court ordered a retrial and transferred it to Mumbai. A fair trial needs an impartial judge and an atmosphere in which witnesses can speak without fear.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-198","question":"In A. K. Kraipak v. Union of India (1969), a member of a selection board was himself a candidate for the post, though he stayed out when his own name was considered. The Supreme Court:","options":["Upheld the selection, since he withdrew from the meeting while his own case was considered","Upheld the selection, since natural justice binds only judicial and quasi-judicial bodies","Quashed the selection: the rule against bias applies to administrative action too","Quashed the selection only because the board had not recorded reasons for its ranking"],"answer":2,"explanation":"The Court held that the line between administrative and quasi-judicial functions is thin and that natural justice, including the rule against bias, applies to administrative decisions as well. His presence while rival candidates were assessed vitiated the selection.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-199","question":"A Tamil Nadu law abolished the hereditary right of succession to the office of archaka (temple priest) and let trustees appoint qualified persons. In Seshammal v. State of Tamil Nadu (1972), the Supreme Court:","options":["Struck it down, as hereditary succession to priestly office is an essential religious practice","Struck it down under Article 26, since only the denomination may appoint its own priests","Upheld it, since Article 25(2)(b) lets the State reform every Hindu religious practice","Upheld it, since appointing an archaka is a secular act, though his rituals are religious"],"answer":3,"explanation":"The Court held that appointing an archaka is a secular function of the trustee; the religious part is the worship he performs, which the law did not touch, and the Agamas on who may perform it must still be followed. Article 25(2)(b) covers social welfare and reform, not every practice.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-200","question":"In Chintaman Rao v. State of Madhya Pradesh (1950), a law barred everyone in certain villages from making bidis during the agricultural season, so that labour would be free for farming. The Supreme Court struck it down because:","options":["A total ban that went beyond what its object needed was not a ‘reasonable’ restriction","The freedom of trade in Article 19(1)(g) cannot be restricted by a State law at all","Bidi making is a cottage industry protected absolutely by the directive in Article 43","Restrictions on trade under Article 19(6) can be imposed only during a National Emergency"],"answer":0,"explanation":"The Court held that a restriction is reasonable only if it is not arbitrary or excessive beyond what the public interest requires; barring even persons who were not farm workers went far beyond the object. It was among the first cases to explain ‘reasonable restrictions’.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-201","question":"In Triveniben v. State of Gujarat (1989), a Constitution Bench considered whether delay in executing a death sentence can be a ground to commute it. It held that:","options":["A delay of over two years after sentence automatically entitles the convict to commutation","Only delay after the judicial process ends counts, and no fixed period can be laid down","Delay can never be a ground, since the convict himself causes it by filing petitions","Delay counts only if it occurs before the High Court confirms the death sentence"],"answer":1,"explanation":"The Bench rejected the fixed two-year rule of T. V. Vatheeswaran (1983) and held that only delay after the judicial process is over, such as in deciding mercy petitions, may be considered, weighing all the circumstances; no fixed period applies.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-202","question":"In Rajasthan State Electricity Board v. Mohan Lal (1967), the Supreme Court interpreted the phrase ‘other authorities’ in Article 12. It held that:","options":["Only bodies performing governmental or sovereign functions are covered by the phrase","The phrase must be read ejusdem generis with Parliament and the State Legislatures","Statutory bodies with power to issue binding directions are covered by the phrase","Only bodies wholly funded out of the Consolidated Fund of India are covered by it"],"answer":2,"explanation":"The Court refused to read ‘other authorities’ ejusdem generis with the bodies named before it and held that authorities created by statute, with power to issue binding directions whose breach is punishable, fall within Article 12, even if some of their activities are commercial.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-203","question":"Consider these statements: 1. Article 16(4) uses the words ‘socially and educationally backward classes’, like Article 15(4). 2. Article 16(4) requires that the backward class be not adequately represented in the services under the State. 3. Article 15(4) covers special provisions for Scheduled Castes and Scheduled Tribes as well as for other backward classes. Which of these are correct?","options":["1 and 2 only","1 and 3 only","1, 2 and 3","2 and 3 only"],"answer":3,"explanation":"Article 16(4) speaks only of ‘any backward class of citizens’ which, in the State's opinion, is not adequately represented, while Article 15(4) names socially and educationally backward classes and the SCs and STs. So 2 and 3 are correct and 1 is wrong.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-204","question":"In Sri Venkataramana Devaru v. State of Mysore (1958), a law threw open a denominational temple to all classes of Hindus, and the denomination claimed protection under Article 26(b). The Supreme Court:","options":["Applied the temple-entry law but let the denomination keep others out of certain rituals","Held that Article 26(b) prevails, so the denomination could keep its temple closed to others","Held that Article 25(2)(b) applies only to temples not owned by any religious denomination","Struck down the law, since temples can be opened to all only by a constitutional amendment"],"answer":0,"explanation":"Using harmonious construction, the Court held that the denomination's right under Article 26(b) is subject to a law under Article 25(2)(b) throwing open Hindu religious institutions of a public character, but allowed it to exclude outsiders from certain special ceremonies.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-205","question":"Section 62(5) of the Representation of the People Act, 1951 bars persons confined in prison from voting. In Anukul Chandra Pradhan v. Union of India (1997), the Supreme Court:","options":["Struck it down, since the right to vote is a Fundamental Right under Article 21","Upheld it, since voting is a statutory right that a law may reasonably limit","Struck it down only as applied to undertrials who have not yet been convicted","Upheld it, since Article 326 itself expressly excludes prisoners from voting"],"answer":1,"explanation":"The Court held that voting is a statutory right, not a Fundamental Right, and that keeping persons in prison away from the electoral process is a reasonable classification, even for undertrials. Article 326 allows disqualification for crime by law but does not itself name prisoners.","difficulty":"hard","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-fundamental-rights-206","question":"In Sodan Singh v. New Delhi Municipal Committee (1989), on street hawking, the Supreme Court held that:","options":["Hawking on public streets is a public nuisance that falls wholly outside Article 19(1)(g)","Hawkers have a Fundamental Right to a fixed place of business on any public road","Hawking is a trade under Article 19(1)(g), subject to reasonable regulation by the State","Hawking is protected under Article 21 alone, so no licence can ever be required for it"],"answer":2,"explanation":"The Court held that street trading is a business protected by Article 19(1)(g) but subject to reasonable restrictions; hawkers have no right to occupy any particular spot, and the State may regulate where and how they trade.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-fundamental-rights-207","question":"Match the case with the relief or principle it is known for: A. Rudul Sah v. State of Bihar (1983) B. Nilabati Behera v. State of Orissa (1993) C. Chairman, Railway Board v. Chandrima Das (2000) D. Bodhisattwa Gautam v. Subhra Chakraborty (1996) — 1. Compensation to a foreign national raped by railway employees 2. Compensation for a custodial death, with sovereign immunity no defence 3. Compensation for detention continued for years after acquittal 4. Rape violates Article 21 even when committed by a private person","options":["A-3, B-1, C-2, D-4","A-2, B-3, C-1, D-4","A-3, B-2, C-4, D-1","A-3, B-2, C-1, D-4"],"answer":3,"explanation":"Rudul Sah was the first award of compensation under Article 32 for illegal detention; Nilabati Behera treated it as a public law remedy based on strict liability; Chandrima Das applied Article 21 to a Bangladeshi national; and Bodhisattwa Gautam held rape to violate the victim's right to life.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-208","question":"How many of these statements about the Aadhaar judgment, K. S. Puttaswamy v. Union of India (2018), are correct? I. It upheld the Aadhaar Act as broadly valid. II. It struck down Section 7, which made Aadhaar mandatory for subsidies and benefits. III. It upheld mandatory linking of Aadhaar with bank accounts and mobile numbers. IV. It upheld linking Aadhaar with PAN under Section 139AA of the Income-tax Act.","options":["Only three","All four","Only two","Only one"],"answer":2,"explanation":"I and IV are correct. II is wrong: Section 7 (Aadhaar for subsidies) was upheld; it was Section 57 (use by private entities) that was struck down. III is wrong: mandatory linking with bank accounts and mobile numbers was struck down.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-209","question":"In Commissioner of Police v. Acharya Jagadishwarananda Avadhuta (2004), the Supreme Court considered the performance of the tandava dance in public processions by the Ananda Margis. It held that:","options":["The dance is protected by Article 26, since the Ananda Marga is a religious denomination","The dance in public is not an essential practice of the faith, so it is not protected","The dance is protected because a sect's own scriptures alone decide what is essential","The dance may be restricted only during a National Emergency proclaimed under Article 352"],"answer":1,"explanation":"Although Ananda Marga is a religious denomination, the Court held that tandava in public was a later addition and not an essential part of its religion, so a police ban on it in processions did not violate Articles 25 and 26. Being a denomination does not protect every practice.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-210","question":"In X v. Principal Secretary, Health and Family Welfare Department (2022), the Supreme Court read the Medical Termination of Pregnancy law and rules to hold that:","options":["Only married women may end a pregnancy between 20 and 24 weeks of gestation","A pregnancy beyond 12 weeks may be ended only with the husband's written consent","Unmarried women may end a pregnancy up to 24 weeks, just like married women","No pregnancy may be ended after 20 weeks except to save the life of the woman"],"answer":2,"explanation":"Holding that excluding unmarried women would violate Article 14 and their reproductive autonomy under Article 21, the Court read the 24-week category to cover all women, married or not.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-211","question":"In Joginder Kumar v. State of U.P. (1994), the Supreme Court laid down that:","options":["Police may arrest on any complaint, provided the person is produced in court within 24 hours","No arrest may be made in a cognisable case without a warrant issued by a magistrate","Every arrest must be video-recorded and the recording kept for at least one year","Arrest needs justification beyond mere power, and a friend or relative must be informed"],"answer":3,"explanation":"The Court held that having the power to arrest is one thing and justifying its use another, and that an arrested person is entitled to have someone told of the arrest and where he is held. These safeguards were expanded in D. K. Basu (1997).","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-fundamental-rights-212","question":"In A. K. Roy v. Union of India (1982), the Supreme Court upheld the National Security Act, 1980. On the 44th Amendment's clause changing the composition of Advisory Boards, which the government had not brought into force, it held that:","options":["No mandamus could compel the government to bring the clause into force","The clause came into force on its own, since an Amendment cannot be left unnotified","The clause was void, since Advisory Boards lie outside Parliament's amending power","Detentions under the NSA were invalid until the clause was brought into force"],"answer":0,"explanation":"The 44th Amendment Act let the Central Government notify different dates for different provisions, and the majority held that no mandamus could issue to force it to notify the Advisory Board clause. That clause has still not been brought into force.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-213","question":"Assertion (A): A State may reserve a share of posts in its services for women, even though Article 16(2) forbids discrimination in public employment on the ground of sex. Reason (R): In Government of Andhra Pradesh v. P. B. Vijayakumar (1995), the Supreme Court held that Article 15(3) permits special provisions for women in State employment as well.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Vijayakumar held that Article 16 must be read with Article 15(3), so special provisions for women in State posts are valid; Article 16(2) bars discrimination on the ground only of sex, not measures in favour of women. R therefore explains A.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-214","question":"In Khoday Distilleries v. State of Karnataka (1995), the Supreme Court held about trade in potable liquor that:","options":["It is a trade like any other, protected by Article 19(1)(g) subject to Article 19(6)","There is no Fundamental Right to trade in it, and the State may ban or monopolise it","Only Parliament can regulate it, since alcohol is a Union List subject in Schedule VII","It can be restricted only on the grounds of public order listed in Article 19(2)"],"answer":1,"explanation":"The Court held that trade in potable liquor is res extra commercium, so there is no Fundamental Right to carry it on; the State may prohibit it or allow it only through licences or a State monopoly. Intoxicating liquor is a State List subject.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-215","question":"In S. P. Mittal v. Union of India (1983), on the Auroville (Emergency Provisions) Act, 1980, which took over the management of Auroville from the Sri Aurobindo Society, the Supreme Court held that the Society:","options":["Was a religious denomination whose management could not be taken over by any law","Was a linguistic minority entitled to protection under Article 29(1) against takeover","Was not a religious denomination, so it could not claim the protection of Article 26","Was a minority educational institution protected by Article 30 against any takeover"],"answer":2,"explanation":"The majority held that Sri Aurobindo's teachings are a philosophy, not a religion, so the Society was not a religious denomination and could not invoke Article 26; the takeover of management was upheld.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-216","question":"Consider these statements: 1. Article 31B protects only laws placed in the Ninth Schedule. 2. Article 31C, as it now stands, protects a law giving effect to Article 39(b) or (c) from challenge under Articles 14 and 19. 3. Article 31A saves laws for the acquisition of estates from challenge under Articles 14 and 19. Which of these are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Article 31B shields Ninth Schedule laws from challenge on any Fundamental Right (subject to the basic structure, per Coelho); Article 31A saves five kinds of laws, starting with acquisition of estates, from Articles 14 and 19; and Article 31C saves laws for Article 39(b) and (c) from Articles 14 and 19.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-217","question":"In Indian Express Newspapers v. Union of India (1985), on import duty levied on newsprint, the Supreme Court held that:","options":["The press is wholly immune from taxation, since any tax on it burdens free speech","The press can be taxed, but a levy that cripples circulation can be struck down","Taxes on the press can be tested only under Article 265 and never under Article 19","A newsprint duty is valid only if the Press Council of India approves it in advance"],"answer":1,"explanation":"The Court held that newspapers are not immune from ordinary taxation, but an excessive tax that curtails circulation can be challenged under Article 19(1)(a); it directed the government to re-examine the levy.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-218","question":"In Ramana Dayaram Shetty v. International Airport Authority of India (1979), the Authority accepted a tender from a person who did not meet its own condition of being a registered second-class hotelier. The Supreme Court held that:","options":["The government may contract with anyone it likes, since its contracts lie outside Part III","The tender was valid, because the Authority is not ‘State’ within Article 12","A public authority cannot arbitrarily depart from the standards it has itself laid down","Only the Comptroller and Auditor General can review the award of a public contract"],"answer":2,"explanation":"The Court held the Authority to be an instrumentality of the State and said that even in awarding contracts it must act fairly and keep to the eligibility standards it has set, or the action is arbitrary under Article 14. On the facts it did not set aside the contract.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-219","question":"A person is detained under a preventive detention law. Under Article 22(5) and the rule in Harikisan v. State of Maharashtra (1962), which of these will make the detention invalid?","options":["The grounds were served only in English, which the detenu could not read or understand","Some facts were withheld because the authority found their disclosure against public interest","The detenu was not allowed to be represented by a lawyer before the Advisory Board","The detenu was not produced before a magistrate within 24 hours of the detention"],"answer":0,"explanation":"Article 22(5) requires the grounds to be communicated so the detenu can make an effective representation, and Harikisan held that grounds in a language he does not understand are not communicated. Withholding facts is allowed by Article 22(6), and Article 22(3) excludes preventive detenus from the lawyer and 24-hour safeguards.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-220","question":"In Arnesh Kumar v. State of Bihar (2014), the Supreme Court gave directions to prevent needless arrests. They apply mainly to offences punishable with imprisonment of:","options":["Up to three years, and require a magistrate's warrant for every arrest","Up to seven years, and require the police to record reasons for an arrest","More than ten years, and require a Superintendent to approve the arrest","Any term, but only for offences under the dowry and domestic violence laws"],"answer":1,"explanation":"For offences punishable with up to seven years, police must be satisfied of the need to arrest under Section 41 CrPC and record reasons using a checklist, and magistrates must not authorise detention mechanically. The case arose under Section 498A IPC, but the directions are general.","difficulty":"moderate","source":"UPSC Prelims · State PSCs"},
  {"id":"polity-fundamental-rights-221","question":"In Mr X v. Hospital Z (1998), a hospital disclosed to a man's fiancée that he was HIV-positive, and the marriage was called off. The Supreme Court held that:","options":["The disclosure violated his right to privacy, so the hospital had to pay damages","Doctors may never disclose a patient's condition to anyone without written consent","The disclosure was justified to protect the health of the woman he was to marry","Medical records are State records, so privacy claims against hospitals cannot lie"],"answer":2,"explanation":"The Court held that the right to privacy is not absolute; where disclosure is needed to protect another person's right to life and health, here the intended wife's, the doctor's disclosure is not wrongful.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"polity-fundamental-rights-222","question":"In K. S. Puttaswamy (2017), the plurality laid down tests that any State intrusion into privacy must meet. Which of these is NOT one of them?","options":["There must be a law that authorises the intrusion","The law must pursue a legitimate aim of the State","The means must be proportionate to the object sought","A judicial warrant must be obtained in every case"],"answer":3,"explanation":"The plurality required legality (a law), a legitimate State aim and proportionality between the object and the means adopted; Justice Kaul added procedural guarantees against abuse. A prior judicial warrant in every case was not one of the tests.","difficulty":"hard","source":"UPSC Prelims"},
];

